 -- Helpers are private. Only the three thin entry points are executable by API.
  CREATE FUNCTION public.fn_izo_teren_autorizat(p_proiect bigint,p_lock boolean) RETURNS bigint
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_uid uuid:=public.fn_izo_uid(); v_emp bigint; v_owner boolean;
BEGIN
 IF p_lock THEN
  SELECT employee_id,is_owner INTO v_emp,v_owner FROM public.profiles WHERE id=v_uid FOR SHARE;
 ELSE SELECT employee_id,is_owner INTO v_emp,v_owner FROM public.profiles WHERE id=v_uid; END IF;
 IF v_emp IS NULL THEN RETURN NULL; END IF;
 IF v_owner THEN RETURN v_emp; END IF;
 IF p_lock THEN
  PERFORM 1 FROM public.user_module_access WHERE profile_id=v_uid AND module='executie.izometrie'
   AND access_level IN ('editor','admin') ORDER BY id FOR SHARE;
 ELSE
  PERFORM 1 FROM public.user_module_access WHERE profile_id=v_uid AND module='executie.izometrie' AND access_level IN ('editor','admin');
 END IF;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF p_lock THEN
  PERFORM 1 FROM public.izo_atribuiri WHERE profile_id=v_uid AND proiect_id=p_proiect AND activ
   AND rol='inginer_izometrie' AND current_date BETWEEN valabil_de AND coalesce(valabil_pana,current_date) ORDER BY id FOR SHARE;
 ELSE
  PERFORM 1 FROM public.izo_atribuiri WHERE profile_id=v_uid AND proiect_id=p_proiect AND activ
   AND rol='inginer_izometrie' AND current_date BETWEEN valabil_de AND coalesce(valabil_pana,current_date);
 END IF;
 IF NOT FOUND THEN RETURN NULL; END IF;
 RETURN v_emp;
END $f$;

  CREATE FUNCTION public.fn_izo_teren_entra(p_proiect bigint,p_functie text) RETURNS text
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_n integer; v_lipsa text[];
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED' USING ERRCODE='25001'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
 IF session_user<>'authenticator' OR public.fn_izo_jwt_rol() IS DISTINCT FROM 'authenticated' OR public.fn_izo_uid() IS NULL THEN RETURN 'fara_drept'; END IF;
 IF coalesce(current_setting('izo.montaj_ctx',true),'')<>'' OR coalesce(current_setting('izo.receptie_ctx',true),'')<>''
  OR coalesce(current_setting('izo.registru_tx',true),'')<>'' THEN RETURN 'fara_drept'; END IF;
 IF public.fn_izo_teren_autorizat(p_proiect,false) IS NULL THEN RETURN 'fara_drept'; END IF;
 INSERT INTO public.izo_rata_apeluri(profile_id,functie,fereastra_de_la,n) VALUES(public.fn_izo_uid(),p_functie,date_trunc('minute',clock_timestamp()),1)
 ON CONFLICT(profile_id,functie) DO UPDATE SET
 n=CASE WHEN izo_rata_apeluri.fereastra_de_la=excluded.fereastra_de_la THEN izo_rata_apeluri.n+1 ELSE 1 END,
 fereastra_de_la=excluded.fereastra_de_la RETURNING n INTO v_n;
 IF v_n>30 THEN RETURN 'limita'; END IF;
 v_lipsa:=public.fn_izo_porti_lipsa();
 IF cardinality(v_lipsa)>0 THEN RAISE EXCEPTION 'E4b porti: %',v_lipsa; END IF;
 RETURN NULL;
END $f$;

  CREATE FUNCTION public.fn_izo_pv_lipsa(p_radacini bigint[]) RETURNS bigint[]
 LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT coalesce(array_agg(b.id ORDER BY b.id),'{}'::bigint[]) FROM public.magazie_bucati b
 WHERE b.id=ANY(p_radacini) AND b.aviz_intrare_id IS NOT NULL AND NOT EXISTS
 (SELECT 1 FROM public.izo_documente_intrare d WHERE d.id=b.aviz_intrare_id AND d.eveniment_pv_id IS NOT NULL)
$f$;

  CREATE FUNCTION public.fn_izo_teren_snapshot(p_proiect bigint,p_tronson bigint) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_doc jsonb;
BEGIN
 IF NOT public.fn_izo_citire(p_proiect) OR NOT EXISTS(SELECT 1 FROM public.executie_tronsoane WHERE id=p_tronson AND proiect_id=p_proiect) THEN
  RETURN jsonb_build_object('cod','fara_drept'); END IF;
 -- One statement / one MVCC snapshot, including all mutable rows (never max(id)).
 WITH frunze AS (
  SELECT b.id,b.uid,b.serie,b.serie_canon,b.sarja,b.lungime_mm,b.lungime_cm,b.perete_mm,b.tip_cod,b.stare,b.tronson_id,b.depozit_id,b.server_ver,
   EXISTS(SELECT 1 FROM public.izo_rezervari r WHERE r.bucata_id=b.id AND r.activa AND (r.expira_dupa IS NULL OR r.expira_dupa>now())) rezervata,
   (SELECT r.tronson_id FROM public.izo_rezervari r WHERE r.bucata_id=b.id AND r.activa AND (r.expira_dupa IS NULL OR r.expira_dupa>now())) rezervata_tronson,
   cardinality(public.fn_izo_pv_lipsa(ARRAY[coalesce(b.radacina_id,b.id)]))>0 fara_pv
  FROM public.magazie_bucati b WHERE b.proiect_id=p_proiect AND b.tip_cod IS NOT NULL AND b.stare NOT IN ('taiata','anulata')
   AND NOT EXISTS(SELECT 1 FROM public.magazie_bucati c WHERE c.parinte_id=b.id AND c.stare<>'anulata')
 ), proprii AS (
  SELECT d.*, (d.identificare IS DISTINCT FROM 'nerezolvata' AND d.tip<>'cuplare' AND NOT EXISTS
   (SELECT 1 FROM public.izo_rezervari r WHERE r.declaratie_id=d.id AND r.activa AND (r.expira_dupa IS NULL OR r.expira_dupa>now()))) rezervare_pierduta
  FROM public.izo_declaratii d WHERE d.proiect_id=p_proiect AND d.tronson_id=p_tronson AND d.declarat_de=public.fn_izo_uid()
   AND d.stare NOT IN ('aprobata','respinsa','stearsa')
 )
 SELECT jsonb_build_object('proiect_id',p_proiect,'tronson_id',p_tronson,
 'frunze',coalesce((SELECT jsonb_agg(to_jsonb(f)||jsonb_build_object('disponibila',NOT rezervata AND NOT fara_pv AND
  (stare='pe_tronson' AND tronson_id=p_tronson OR stare IN ('sosit','receptionat','retur') AND depozit_id IS NOT NULL)) ORDER BY f.id) FROM frunze f),'[]'::jsonb),
 'suduri','[]'::jsonb,'numar_urmator',(SELECT CASE WHEN sens_numerotare='descrescator' THEN nr_sudura_start ELSE 1 END FROM public.izo_tronson_config WHERE tronson_id=p_tronson),
 'config',(SELECT to_jsonb(c) FROM public.izo_tronson_config c WHERE tronson_id=p_tronson),
 'praguri',(SELECT to_jsonb(c)-ARRAY['modificat_de','modificat_la'] FROM public.izo_proiect_config c WHERE proiect_id=p_proiect),
 'declaratii',coalesce((SELECT jsonb_agg(to_jsonb(d) ORDER BY d.id) FROM proprii d),'[]'::jsonb),
 'bucati_declarate',coalesce((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.uid) FROM public.izo_bucati_declarate c JOIN proprii d ON d.id=c.declaratie_id),'[]'::jsonb),
 'lanturi',coalesce((SELECT jsonb_agg(to_jsonb(f) ORDER BY f.id) FROM frunze f WHERE stare='montata' AND tronson_id=p_tronson),'[]'::jsonb),
 'tombstone',coalesce((SELECT jsonb_agg(jsonb_build_object('id',b.id,'uid',b.uid,'stare',b.stare,'server_ver',b.server_ver) ORDER BY b.id)
  FROM public.magazie_bucati b WHERE b.proiect_id=p_proiect AND b.tip_cod IS NOT NULL AND b.stare IN ('taiata','anulata')),'[]'::jsonb),
 'server_ver_max',greatest(coalesce((SELECT max(server_ver) FROM public.magazie_bucati WHERE proiect_id=p_proiect),0),
 coalesce((SELECT max(server_ver) FROM public.izo_declaratii WHERE proiect_id=p_proiect),0),
 coalesce((SELECT max(server_ver) FROM public.izo_rezervari WHERE proiect_id=p_proiect),0),
 coalesce((SELECT server_ver FROM public.izo_tronson_config WHERE tronson_id=p_tronson),0))) INTO v_doc;
 RETURN jsonb_build_object('snapshot_id',gen_random_uuid(),'checksum',encode(sha256(convert_to(v_doc::text,'UTF8')),'hex')) || v_doc;
END $f$;

  CREATE FUNCTION public.fn_izo_teren_intern(p_proiect bigint,p_tronson bigint,p_dispozitiv uuid,p_pregateste boolean) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_cod text; v_f public.izo_fronturi; v_owner uuid;
BEGIN
 v_cod:=public.fn_izo_teren_entra(p_proiect,CASE WHEN p_pregateste THEN 'pregateste' ELSE 'instantaneu' END);
 IF v_cod IS NOT NULL THEN RETURN jsonb_build_object('cod',v_cod); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.executie_tronsoane WHERE id=p_tronson AND proiect_id=p_proiect) THEN RETURN jsonb_build_object('cod','fara_drept'); END IF;
 IF p_pregateste THEN
  BEGIN
  IF p_dispozitiv IS NULL THEN RETURN jsonb_build_object('cod','eroare'); END IF;
  -- Tronson-scoped front arbitration. No project advisory (activation order §10.5).
  INSERT INTO public.izo_dispozitive(dispozitiv_id,profile_id) VALUES(p_dispozitiv,public.fn_izo_uid()) ON CONFLICT DO NOTHING;
  SELECT profile_id INTO v_owner FROM public.izo_dispozitive WHERE dispozitiv_id=p_dispozitiv;
  IF v_owner IS DISTINCT FROM public.fn_izo_uid() THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='IZ004'; END IF;
  INSERT INTO public.izo_fronturi(proiect_id,tronson_id,profile_id,dispozitiv_id,expira_la)
   VALUES(p_proiect,p_tronson,public.fn_izo_uid(),p_dispozitiv,now()+interval '12 hours') ON CONFLICT DO NOTHING;
  SELECT * INTO v_f FROM public.izo_fronturi WHERE tronson_id=p_tronson AND activ FOR UPDATE;
  IF v_f.profile_id<>public.fn_izo_uid() OR v_f.dispozitiv_id<>p_dispozitiv THEN RAISE EXCEPTION 'alt_dispozitiv' USING ERRCODE='IZ004'; END IF;
  IF public.fn_izo_teren_autorizat(p_proiect,true) IS NULL THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='IZ004'; END IF;
  PERFORM 1 FROM public.izo_tronson_config WHERE tronson_id=p_tronson FOR SHARE;
  IF NOT EXISTS(SELECT 1 FROM public.izo_tronson_config WHERE tronson_id=p_tronson AND flux_montaj)
   OR coalesce(public.fn_izo_nivel(p_proiect),'off') NOT IN ('stoc','montaj') THEN RAISE EXCEPTION 'flux_inactiv'; END IF;
  PERFORM 1 FROM public.magazie_bucati WHERE proiect_id=p_proiect AND id=radacina_id ORDER BY id FOR UPDATE;
  UPDATE public.izo_fronturi SET expira_la=now()+interval '12 hours',server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_f.id;
   UPDATE public.izo_rezervari SET expira_dupa=now()+interval '36 hours',server_ver=nextval('public.izo_server_ver_seq')
   WHERE autor_profile_id=public.fn_izo_uid() AND tronson_id=p_tronson AND activa AND expira_dupa IS NOT NULL;
  EXCEPTION WHEN SQLSTATE 'IZ004' THEN RETURN jsonb_build_object('cod',SQLERRM); END;
 ELSE
  IF public.fn_izo_teren_autorizat(p_proiect,true) IS NULL THEN RETURN jsonb_build_object('cod','fara_drept'); END IF;
 END IF;
 RETURN public.fn_izo_teren_snapshot(p_proiect,p_tronson);
END $f$;

  CREATE FUNCTION public.fn_izo_teren_instantaneu(p_proiect bigint,p_tronson bigint) RETURNS jsonb
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT public.fn_izo_teren_intern(p_proiect,p_tronson,NULL,false)
$f$;

  CREATE FUNCTION public.fn_izo_teren_payload(p_payload jsonb) RETURNS jsonb
 LANGUAGE plpgsql IMMUTABLE SECURITY INVOKER SET search_path = public, pg_temp AS $f$
DECLARE v_p jsonb:=p_payload-'gps'; v_key text; v_allowed text[];
BEGIN
 IF jsonb_typeof(v_p) IS DISTINCT FROM 'object' OR v_p-ARRAY['proiect_id','tronson_id','uid','preverificare_uid','versiune_baza','tip',
 'zi','bucata','sursa','baza_mm','puncte_mm','copii','confirmare','capat_amonte','amonte','sudura','lungime_montata_mm',
 'depinde_de_uid','depinde_de_versiune','serie_bruta','sarja_declarata','perete_declarat','lungime_masurata_mm',
 'ultimele3_reconfirmate','km_propus_m','executant','poanson','data_montaj','randuri']<>'{}'::jsonb THEN
  RAISE EXCEPTION 'payload' USING ERRCODE='IZ001'; END IF;
 IF jsonb_path_exists(v_p,'$.**.gps') OR jsonb_path_exists(v_p,'$.**.lat') OR jsonb_path_exists(v_p,'$.**.lon') THEN
  RAISE EXCEPTION 'gps_nested' USING ERRCODE='IZ001'; END IF;
 FOREACH v_key IN ARRAY ARRAY['bucata','sursa','confirmare','amonte','sudura'] LOOP
  IF v_p ? v_key THEN
   v_allowed:=CASE v_key WHEN 'bucata' THEN ARRAY['bucata_id','decl_uid'] WHEN 'sursa' THEN ARRAY['bucata_id','decl_uid']
    WHEN 'confirmare' THEN ARRAY['mod','cm','la','masurata_mm'] WHEN 'amonte' THEN ARRAY['tip','bucata_id','decl_uid','capat']
    ELSE ARRAY['nr','sufix'] END;
   IF jsonb_typeof(v_p->v_key)<>'object' OR (v_p->v_key)-v_allowed<>'{}'::jsonb THEN RAISE EXCEPTION 'payload_nested' USING ERRCODE='IZ001'; END IF;
  END IF;
 END LOOP;
 IF v_p ? 'copii' AND EXISTS(SELECT 1 FROM jsonb_array_elements(v_p->'copii') c WHERE
  jsonb_typeof(c)<>'object' OR c-ARRAY['uid','lungime_mm','destinatie','depozit_destinatie_id','calculata']<>'{}'::jsonb) THEN
  RAISE EXCEPTION 'copii_payload' USING ERRCODE='IZ001'; END IF;
 IF v_p ? 'randuri' AND EXISTS(SELECT 1 FROM jsonb_array_elements(v_p->'randuri') c WHERE
  jsonb_typeof(c)<>'object' OR c-ARRAY['uid','versiune']<>'{}'::jsonb) THEN RAISE EXCEPTION 'randuri_payload' USING ERRCODE='IZ001'; END IF;
 RETURN v_p;
END $f$;

  CREATE FUNCTION public.fn_izo_teren_op(p_dispozitiv uuid,p_op jsonb,p_payload jsonb,p_emp bigint,p_hash text,p_front public.izo_fronturi) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_s public.izo_preverificari; v_d public.izo_declaratii; v_b public.magazie_bucati;
 v_c public.izo_bucati_declarate; v_cfg public.izo_proiect_config;
 v_uid uuid:=public.fn_izo_uid(); v_type text:=p_op->>'tip_op'; v_id uuid:=(p_op->>'op_id')::uuid;
 v_p jsonb:=p_payload; v_ref jsonb; v_child jsonb; v_source bigint; v_decl uuid; v_root bigint;
 v_len integer; v_base integer; v_sum integer; v_n integer; v_i integer; v_letter integer; v_points integer[];
 v_code text; v_left text; v_right text; v_prev text; v_state text:='ciorna'; v_ident text;
 v_conflict text; v_date date; v_json jsonb; v_response jsonb; v_gps jsonb; v_affected bigint;
BEGIN
 IF (p_op->>'versiune_format')::integer IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'versiune_format' USING ERRCODE='IZ001'; END IF;
 IF v_type='sesiune_deschide' THEN
  SELECT * INTO v_s FROM public.izo_preverificari WHERE uid=(v_p->>'uid')::uuid;
  IF FOUND THEN
   IF v_s.autor_profile_id<>v_uid OR v_s.proiect_id<>p_front.proiect_id OR v_s.tronson_id<>p_front.tronson_id THEN
    RAISE EXCEPTION 'ref_alt_autor' USING ERRCODE='IZ001'; END IF;
   RETURN jsonb_build_object('cod','acceptat','sesiune_id',v_s.id,'versiune',v_s.versiune);
  END IF;
  IF (v_p->>'zi')::date IS DISTINCT FROM (now() AT TIME ZONE 'Europe/Bucharest')::date THEN RAISE EXCEPTION 'zi' USING ERRCODE='IZ001'; END IF;
  INSERT INTO public.izo_preverificari(uid,proiect_id,tronson_id,autor_profile_id,dispozitiv_id)
   VALUES((v_p->>'uid')::uuid,p_front.proiect_id,p_front.tronson_id,v_uid,p_dispozitiv) RETURNING * INTO v_s;
  RETURN jsonb_build_object('cod','acceptat','sesiune_id',v_s.id,'versiune',v_s.versiune);
 END IF;
 SELECT * INTO v_s FROM public.izo_preverificari WHERE uid=(v_p->>'preverificare_uid')::uuid;
 IF NOT FOUND OR v_s.autor_profile_id<>v_uid OR v_s.proiect_id<>p_front.proiect_id OR v_s.tronson_id<>p_front.tronson_id THEN
  RAISE EXCEPTION 'ref_alt_autor' USING ERRCODE='IZ001'; END IF;
 IF v_s.stare<>'deschisa' THEN RAISE EXCEPTION 'sesiune_stare' USING ERRCODE='IZ002'; END IF;
 IF v_type='sesiune_trimite' THEN
  IF EXISTS(SELECT 1 FROM public.izo_declaratii WHERE preverificare_id=v_s.id AND stare IN ('conflict','blocata','revizie_ceruta')) THEN
   RAISE EXCEPTION 'rand_blocant' USING ERRCODE='IZ002'; END IF;
  IF (SELECT coalesce(jsonb_agg(jsonb_build_object('uid',uid,'versiune',versiune) ORDER BY uid),'[]'::jsonb)
    FROM public.izo_declaratii WHERE preverificare_id=v_s.id AND stare='ciorna') IS DISTINCT FROM
   (SELECT coalesce(jsonb_agg(x ORDER BY x->>'uid'),'[]'::jsonb) FROM jsonb_array_elements(v_p->'randuri') x) THEN
   RAISE EXCEPTION 'cas' USING ERRCODE='IZ002'; END IF;
  IF EXISTS(SELECT 1 FROM public.izo_declaratii d WHERE preverificare_id=v_s.id AND stare='ciorna' AND identificare IS DISTINCT FROM 'nerezolvata'
   AND NOT EXISTS(SELECT 1 FROM public.izo_rezervari r WHERE r.declaratie_id=d.id AND r.activa AND (r.expira_dupa IS NULL OR r.expira_dupa>now()))) THEN
   RAISE EXCEPTION 'rezervare_pierduta' USING ERRCODE='IZ002'; END IF;
  UPDATE public.izo_declaratii SET stare=CASE WHEN identificare='nerezolvata' THEN 'in_verificare' ELSE 'trimisa' END,
   server_ver=nextval('public.izo_server_ver_seq') WHERE preverificare_id=v_s.id AND stare='ciorna';
  UPDATE public.izo_rezervari SET expira_dupa=NULL,server_ver=nextval('public.izo_server_ver_seq') WHERE activa
   AND declaratie_id IN (SELECT id FROM public.izo_declaratii WHERE preverificare_id=v_s.id);
  UPDATE public.izo_preverificari SET stare='trimisa',trimisa_la=now(),trimisa_op_id=v_id,versiune=versiune+1,
   server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_s.id;
  RETURN jsonb_build_object('cod','acceptat','sesiune_id',v_s.id);
 END IF;
 IF v_type NOT IN ('decl_salveaza','decl_sterge') THEN RAISE EXCEPTION 'tip_op' USING ERRCODE='IZ001'; END IF;
 SELECT * INTO v_d FROM public.izo_declaratii WHERE uid=(v_p->>'uid')::uuid;
 IF FOUND THEN
  IF v_d.declarat_de<>v_uid OR v_d.preverificare_id<>v_s.id THEN RAISE EXCEPTION 'ref_alt_autor' USING ERRCODE='IZ001'; END IF;
  IF v_d.versiune IS DISTINCT FROM (v_p->>'versiune_baza')::integer OR v_d.stare NOT IN ('ciorna','conflict','blocata','in_verificare','revizie_ceruta') THEN
   RAISE EXCEPTION 'cas' USING ERRCODE='IZ002'; END IF;
 ELSE
  IF (v_p->>'versiune_baza')::integer IS DISTINCT FROM 0 OR v_type='decl_sterge' THEN RAISE EXCEPTION 'cas' USING ERRCODE='IZ002'; END IF;
 END IF;
 IF v_d.id IS NOT NULL THEN
  -- Entire author/project declaration closure was locked before any root lock.
  WITH RECURSIVE deps AS (SELECT uid FROM public.izo_declaratii WHERE depinde_de_uid=v_d.uid
   UNION SELECT d.uid FROM public.izo_declaratii d JOIN deps x ON d.depinde_de_uid=x.uid)
  UPDATE public.izo_declaratii SET stare_inainte_blocare=stare,stare='blocata',blocata_motiv='parinte_modificat',server_ver=nextval('public.izo_server_ver_seq')
   WHERE uid IN (SELECT uid FROM deps) AND stare IN ('ciorna','conflict','trimisa','in_verificare','revizie_ceruta');
  UPDATE public.izo_rezervari SET activa=false,eliberata_la=now(),motiv_eliberare=CASE WHEN v_type='decl_sterge' THEN 'stearsa' ELSE 'versiune_noua' END,
   server_ver=nextval('public.izo_server_ver_seq') WHERE declaratie_id=v_d.id AND activa;
  UPDATE public.izo_bucati_declarate SET stare='anulata',server_ver=nextval('public.izo_server_ver_seq') WHERE declaratie_id=v_d.id AND stare='declarata';
 END IF;
 IF v_type='decl_sterge' THEN
  UPDATE public.izo_declaratii SET stare='stearsa',stare_inainte_blocare=NULL,blocata_motiv=NULL,versiune=versiune+1,ultimul_op_id=v_id,
   server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_d.id RETURNING * INTO v_d;
  INSERT INTO public.izo_declaratii_versiuni(declaratie_id,versiune,payload,hash_cerere,op_id) VALUES(v_d.id,v_d.versiune,v_p,p_hash,v_id);
  RETURN jsonb_build_object('cod','acceptat','uid',v_d.uid,'versiune',v_d.versiune,'stare',v_d.stare);
 END IF;
 IF v_p->>'tip' NOT IN ('montaj','taiere') OR v_p->>'tip' IS NULL THEN
  RAISE EXCEPTION 'necesita_suduri_capete_E4b2' USING ERRCODE='IZ001'; END IF;
 IF v_p ? 'depinde_de_uid' THEN
  IF NOT EXISTS(SELECT 1 FROM public.izo_declaratii WHERE uid=(v_p->>'depinde_de_uid')::uuid AND declarat_de=v_uid
   AND proiect_id=p_front.proiect_id AND tronson_id=p_front.tronson_id AND versiune=(v_p->>'depinde_de_versiune')::integer
   AND stare IN ('ciorna','trimisa')) THEN RAISE EXCEPTION 'dependenta' USING ERRCODE='IZ003'; END IF;
  IF (v_p->>'depinde_de_uid')::uuid=(v_p->>'uid')::uuid THEN RAISE EXCEPTION 'ciclu' USING ERRCODE='IZ001'; END IF;
  IF EXISTS(WITH RECURSIVE parinti AS (
   SELECT uid,depinde_de_uid FROM public.izo_declaratii WHERE uid=(v_p->>'depinde_de_uid')::uuid
   UNION SELECT d.uid,d.depinde_de_uid FROM public.izo_declaratii d JOIN parinti p ON d.uid=p.depinde_de_uid)
   SELECT 1 FROM parinti WHERE uid=(v_p->>'uid')::uuid) THEN RAISE EXCEPTION 'ciclu' USING ERRCODE='IZ001'; END IF;
 END IF;
 v_date:=coalesce((v_p->>'data_montaj')::date,(now() AT TIME ZONE 'Europe/Bucharest')::date);
 IF v_date>(now() AT TIME ZONE 'Europe/Bucharest')::date THEN RAISE EXCEPTION 'data_viitoare' USING ERRCODE='IZ001'; END IF;
 SELECT * INTO STRICT v_cfg FROM public.izo_proiect_config WHERE proiect_id=p_front.proiect_id;
 v_ref:=CASE WHEN v_p->>'tip'='taiere' THEN v_p->'sursa' ELSE v_p->'bucata' END;
 v_source:=(v_ref->>'bucata_id')::bigint; v_decl:=(v_ref->>'decl_uid')::uuid;
 IF num_nonnulls(v_source,v_decl)>1 THEN RAISE EXCEPTION 'resursa' USING ERRCODE='IZ001'; END IF;
 IF v_decl IS NOT NULL THEN
  SELECT * INTO v_c FROM public.izo_bucati_declarate WHERE uid=v_decl;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM public.izo_declaratii WHERE id=v_c.declaratie_id AND declarat_de=v_uid
   AND proiect_id=p_front.proiect_id AND tronson_id=p_front.tronson_id AND uid=(v_p->>'depinde_de_uid')::uuid
   AND versiune=(v_p->>'depinde_de_versiune')::integer AND stare IN ('ciorna','trimisa')) THEN
   RAISE EXCEPTION 'ref_alt_autor' USING ERRCODE='IZ001'; END IF;
  SELECT id INTO v_source FROM public.magazie_bucati WHERE uid=v_decl;
  IF v_source IS NOT NULL THEN v_decl:=NULL;
  ELSIF v_c.stare<>'declarata' OR v_c.destinatie<>'montaj' THEN RAISE EXCEPTION 'copil_indisponibil' USING ERRCODE='IZ002'; END IF;
 END IF;
 IF v_source IS NOT NULL THEN
  SELECT * INTO v_b FROM public.magazie_bucati WHERE id=v_source;
  IF NOT FOUND OR v_b.proiect_id<>p_front.proiect_id OR v_b.tip_cod IS NULL THEN RAISE EXCEPTION 'bucata' USING ERRCODE='IZ001'; END IF;
  IF v_b.stare='carantina' THEN RAISE EXCEPTION 'carantina' USING ERRCODE='IZ001'; END IF;
  IF NOT (v_b.stare='pe_tronson' AND v_b.tronson_id=p_front.tronson_id OR v_b.stare IN ('sosit','receptionat','retur') AND v_b.depozit_id IS NOT NULL) THEN
   RAISE EXCEPTION 'stare_bucata' USING ERRCODE='IZ002'; END IF;
  v_root:=coalesce(v_b.radacina_id,v_b.id); v_len:=v_b.lungime_mm;
  IF cardinality(public.fn_izo_pv_lipsa(ARRAY[v_root]))>0 THEN RAISE EXCEPTION 'fara_pv' USING ERRCODE='IZ001'; END IF;
  IF v_b.stare='pe_tronson' AND EXISTS(SELECT 1 FROM public.magazie_bucati_miscari m JOIN public.magazie_bucati_evenimente e ON e.id=m.eveniment_id
   WHERE m.bucata_id=v_source AND e.tip='livrare' AND (e.ora_server AT TIME ZONE 'Europe/Bucharest')::date>v_date) THEN
   RAISE EXCEPTION 'data_inainte_iesire' USING ERRCODE='IZ001'; END IF;
 ELSE
  v_root:=v_c.radacina_id; v_len:=v_c.lungime_mm;
  IF v_root IS NOT NULL THEN SELECT * INTO v_b FROM public.magazie_bucati WHERE id=v_root; END IF;
 END IF;
 IF v_source IS NULL AND v_decl IS NULL THEN
  IF v_p->>'tip'<>'montaj' OR length(coalesce(v_p->>'serie_bruta',''))=0 OR (v_p->>'lungime_masurata_mm')::integer IS NULL THEN
   RAISE EXCEPTION 'identificare' USING ERRCODE='IZ001'; END IF;
  v_ident:='nerezolvata'; v_len:=(v_p->>'lungime_masurata_mm')::integer;
 ELSE v_ident:=CASE WHEN v_decl IS NULL THEN 'bucata' ELSE 'bucata_decl' END; END IF;
 IF v_len IS NULL OR v_len<=0 OR v_len>v_cfg.lungime_max_mm THEN RAISE EXCEPTION 'lungime' USING ERRCODE='IZ001'; END IF;
 IF coalesce(v_p#>>'{confirmare,mod}','') NOT IN ('marcaj','marcaj_diferit','masurat','taiata') THEN RAISE EXCEPTION 'lungime_neconfirmata' USING ERRCODE='IZ001'; END IF;
 IF v_p#>>'{confirmare,mod}'='marcaj' AND (v_p#>>'{confirmare,cm}')::integer IS DISTINCT FROM (round(v_len::numeric/10)::integer % 100) THEN
  RAISE EXCEPTION 'confirmare_cm' USING ERRCODE='IZ001'; END IF;
 IF v_p->>'tip'='montaj' THEN
  IF coalesce(v_p#>>'{amonte,tip}','inceput_lant')<>'inceput_lant' OR v_p ? 'sudura' THEN RAISE EXCEPTION 'necesita_suduri_capete_E4b2' USING ERRCODE='IZ001'; END IF;
  IF (v_p->>'lungime_montata_mm')::integer IS NULL OR (v_p->>'lungime_montata_mm')::integer<>v_len THEN RAISE EXCEPTION 'montaj_lungime' USING ERRCODE='IZ001'; END IF;
 ELSE
  v_base:=(v_p->>'baza_mm')::integer;
  IF v_base IS NULL OR v_base<=0 OR v_base>v_cfg.lungime_max_mm THEN RAISE EXCEPTION 'baza' USING ERRCODE='IZ001'; END IF;
  IF abs(v_base-v_len)>v_cfg.toleranta_mm AND (v_source IS DISTINCT FROM v_root OR EXISTS
   (SELECT 1 FROM public.magazie_bucati WHERE radacina_id=v_root AND id<>v_root AND stare<>'anulata') OR EXISTS
   (SELECT 1 FROM public.izo_bucati_declarate WHERE radacina_id=v_root AND declaratie_id IS DISTINCT FROM v_d.id AND stare<>'anulata')) THEN
   v_state:='conflict'; v_conflict:='corectie_in_arbore'; END IF;
  SELECT array_agg(value::integer ORDER BY ordinality) INTO v_points FROM jsonb_array_elements_text(v_p->'puncte_mm') WITH ORDINALITY;
  v_n:=jsonb_array_length(v_p->'copii');
  IF cardinality(v_points) NOT BETWEEN 1 AND 2 OR v_n IS DISTINCT FROM cardinality(v_points)+1 OR v_points[1]<=0
   OR v_points[cardinality(v_points)]>=v_base OR (cardinality(v_points)=2 AND v_points[1]>=v_points[2]) THEN RAISE EXCEPTION 'puncte' USING ERRCODE='IZ001'; END IF;
  v_sum:=0; v_i:=0;
  FOR v_child IN SELECT value FROM jsonb_array_elements(v_p->'copii') LOOP
   v_i:=v_i+1;
   v_len:=(v_child->>'lungime_mm')::integer;
   IF v_len IS NULL OR v_len<=0 OR v_len IS DISTINCT FROM
    (CASE WHEN v_i=v_n THEN v_base ELSE v_points[v_i] END)-(CASE WHEN v_i=1 THEN 0 ELSE v_points[v_i-1] END) THEN RAISE EXCEPTION 'r3' USING ERRCODE='IZ001'; END IF;
   v_sum:=v_sum+v_len;
   IF v_child->>'destinatie' NOT IN ('montaj','depozit') OR v_child->>'destinatie' IS NULL THEN RAISE EXCEPTION 'destinatie' USING ERRCODE='IZ001'; END IF;
   IF EXISTS(SELECT 1 FROM public.magazie_bucati WHERE uid=(v_child->>'uid')::uuid) OR EXISTS
    (SELECT 1 FROM public.izo_bucati_declarate WHERE uid=(v_child->>'uid')::uuid AND
     (declaratie_id IS DISTINCT FROM v_d.id OR radacina_id IS DISTINCT FROM v_root OR parinte_bucata_id IS DISTINCT FROM v_source OR parinte_decl_uid IS DISTINCT FROM v_decl)) THEN RAISE EXCEPTION 'uid_alt_arbore' USING ERRCODE='IZ002'; END IF;
   IF EXISTS(SELECT 1 FROM public.magazie_bucati b WHERE b.proiect_id=p_front.proiect_id AND b.id IS DISTINCT FROM v_source AND b.stare NOT IN ('taiata','anulata')
    AND b.serie_canon=v_b.serie_canon AND b.sarja IS NOT DISTINCT FROM v_b.sarja AND b.lungime_cm=round(v_len::numeric/10)::integer) THEN
    v_state:='conflict'; v_conflict:='r1d'; END IF;
   IF (SELECT count(*) FROM jsonb_array_elements(v_p->'copii') c WHERE round((c->>'lungime_mm')::numeric/10)=round(v_len::numeric/10))>1 OR EXISTS
    (SELECT 1 FROM public.izo_bucati_declarate c JOIN public.magazie_bucati b ON b.id=c.radacina_id
     WHERE c.stare='declarata' AND c.declaratie_id IS DISTINCT FROM v_d.id AND c.uid IS DISTINCT FROM v_decl
      AND b.serie_canon=v_b.serie_canon AND b.sarja IS NOT DISTINCT FROM v_b.sarja AND round(c.lungime_mm::numeric/10)=round(v_len::numeric/10)) THEN
    v_state:='conflict'; v_conflict:='r1d'; END IF;
  END LOOP;
  IF v_sum<>v_base THEN RAISE EXCEPTION 'r3' USING ERRCODE='IZ001'; END IF;
 END IF;
 -- Stable declaration identity; no facts are written to the registry.
 IF v_d.id IS NULL THEN
  INSERT INTO public.izo_declaratii(uid,preverificare_id,proiect_id,tronson_id,tip,versiune,declarat_de,declarat_de_angajat,dispozitiv_id,ultimul_op_id,
   stare,conflict_cod,identificare,bucata_id,bucata_decl_uid,sursa_bucata_id,sursa_decl_uid,depinde_de_uid,depinde_de_versiune,payload,gps_prezent,data_montaj)
  VALUES((v_p->>'uid')::uuid,v_s.id,p_front.proiect_id,p_front.tronson_id,v_p->>'tip',1,v_uid,p_emp,p_dispozitiv,v_id,v_state,v_conflict,
   CASE WHEN v_p->>'tip'='montaj' THEN v_ident END,CASE WHEN v_p->>'tip'='montaj' THEN v_source END,CASE WHEN v_p->>'tip'='montaj' THEN v_decl END,
   CASE WHEN v_p->>'tip'='taiere' THEN v_source END,CASE WHEN v_p->>'tip'='taiere' THEN v_decl END,
   (v_p->>'depinde_de_uid')::uuid,(v_p->>'depinde_de_versiune')::integer,v_p,(p_op->'payload') ? 'gps',v_date) RETURNING * INTO v_d;
 ELSE
  IF v_d.tip<>v_p->>'tip' THEN RAISE EXCEPTION 'tip_imuabil' USING ERRCODE='IZ001'; END IF;
  UPDATE public.izo_declaratii SET versiune=versiune+1,stare=v_state,conflict_cod=v_conflict,stare_inainte_blocare=NULL,blocata_motiv=NULL,
   identificare=CASE WHEN tip='montaj' THEN v_ident END,bucata_id=CASE WHEN tip='montaj' THEN v_source END,bucata_decl_uid=CASE WHEN tip='montaj' THEN v_decl END,
   sursa_bucata_id=CASE WHEN tip='taiere' THEN v_source END,sursa_decl_uid=CASE WHEN tip='taiere' THEN v_decl END,
   depinde_de_uid=(v_p->>'depinde_de_uid')::uuid,depinde_de_versiune=(v_p->>'depinde_de_versiune')::integer,
   payload=v_p,ultimul_op_id=v_id,gps_prezent=(p_op->'payload') ? 'gps',data_montaj=v_date,
   server_ver=nextval('public.izo_server_ver_seq') WHERE id=v_d.id RETURNING * INTO v_d;
 END IF;
 IF v_source IS NOT NULL OR v_decl IS NOT NULL THEN
  UPDATE public.izo_rezervari SET activa=false,eliberata_la=now(),motiv_eliberare='expirata',server_ver=nextval('public.izo_server_ver_seq')
   WHERE activa AND expira_dupa<now() AND (bucata_id=v_source OR bucata_decl_uid=v_decl);
  INSERT INTO public.izo_rezervari(proiect_id,tronson_id,declaratie_id,declaratie_versiune,autor_profile_id,bucata_id,bucata_decl_uid,din_depozit,expira_dupa)
   VALUES(p_front.proiect_id,p_front.tronson_id,v_d.id,v_d.versiune,v_uid,v_source,v_decl,coalesce(v_b.depozit_id IS NOT NULL,false),p_front.expira_la+interval '24 hours');
 END IF;
 IF v_d.tip='taiere' THEN
  -- Never recycle letters, including letters of cancelled declarations.
  SELECT coalesce(max(x.n),0) INTO v_letter FROM (
   SELECT ascii(left(capat_stanga,1))-65 n FROM public.izo_bucati_declarate WHERE radacina_id=v_root
   UNION ALL SELECT ascii(left(capat_dreapta,1))-65 FROM public.izo_bucati_declarate WHERE radacina_id=v_root
   UNION ALL SELECT ascii(left(capat_stanga,1))-65 FROM public.magazie_bucati WHERE radacina_id=v_root
   UNION ALL SELECT ascii(left(capat_dreapta,1))-65 FROM public.magazie_bucati WHERE radacina_id=v_root) x;
  v_prev:=coalesce(v_c.capat_stanga,v_b.capat_stanga,'A'); v_i:=0;
  FOR v_child IN SELECT value FROM jsonb_array_elements(v_p->'copii') LOOP
   v_i:=v_i+1; v_left:=v_prev;
   IF v_i=v_n THEN v_right:=coalesce(v_c.capat_dreapta,v_b.capat_dreapta,'B');
   ELSE v_letter:=v_letter+1; IF v_letter>25 THEN RAISE EXCEPTION 'litere_epuizate' USING ERRCODE='IZ001'; END IF; v_right:=chr(65+v_letter); END IF;
   INSERT INTO public.izo_bucati_declarate(uid,declaratie_id,declaratie_versiune,parinte_bucata_id,parinte_decl_uid,radacina_id,lungime_mm,lungime_calculata,
    capat_stanga,capat_dreapta,cod_bucata,destinatie,depozit_destinatie_id)
   VALUES((v_child->>'uid')::uuid,v_d.id,v_d.versiune,v_source,v_decl,v_root,(v_child->>'lungime_mm')::integer,coalesce((v_child->>'calculata')::boolean,false),
    v_left,v_right,v_left||v_right,v_child->>'destinatie',(v_child->>'depozit_destinatie_id')::integer)
   ON CONFLICT(uid) DO UPDATE SET declaratie_versiune=excluded.declaratie_versiune,lungime_mm=excluded.lungime_mm,
    lungime_calculata=excluded.lungime_calculata,capat_stanga=excluded.capat_stanga,capat_dreapta=excluded.capat_dreapta,cod_bucata=excluded.cod_bucata,
    destinatie=excluded.destinatie,depozit_destinatie_id=excluded.depozit_destinatie_id,stare='declarata',server_ver=nextval('public.izo_server_ver_seq');
   v_prev:=v_right;
  END LOOP;
 END IF;
 INSERT INTO public.izo_declaratii_versiuni(declaratie_id,versiune,payload,hash_cerere,op_id) VALUES(v_d.id,v_d.versiune,v_p,p_hash,v_id);
 IF (p_op->'payload') ? 'gps' THEN
  v_gps:=p_op#>'{payload,gps}';
  IF jsonb_typeof(v_gps)<>'object' OR v_gps-ARRAY['lat','lon','precizie_m','la']<>'{}'::jsonb THEN RAISE EXCEPTION 'gps' USING ERRCODE='IZ001'; END IF;
  INSERT INTO public.izo_declaratii_gps(declaratie_id,versiune,lat,lon,precizie_m,la)
   VALUES(v_d.id,v_d.versiune,(v_gps->>'lat')::numeric,(v_gps->>'lon')::numeric,(v_gps->>'precizie_m')::numeric,(v_gps->>'la')::timestamptz);
 END IF;
 RETURN jsonb_build_object('cod','acceptat','uid',v_d.uid,'versiune',v_d.versiune,'stare',v_d.stare,'conflict_cod',v_d.conflict_cod);
END $f$;

  CREATE FUNCTION public.fn_izo_teren_push(p_dispozitiv uuid,p_ops jsonb) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_f public.izo_fronturi; v_old public.izo_operatii; v_uid uuid; v_emp bigint;
 v_op jsonb; v_p jsonb; v_results jsonb:='[]'; v_response jsonb; v_hash text;
 v_code text; v_result text; v_state text; v_pr bigint; v_tr bigint; v_seq bigint:=0; v_last bigint;
 v_opid uuid; v_ora timestamptz; v_deps uuid[]:='{}'; v_stop boolean:=false; v_format integer;
BEGIN
 -- No table read or write precedes the schema lock.
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED' USING ERRCODE='25001'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
 IF session_user<>'authenticator' OR public.fn_izo_jwt_rol() IS DISTINCT FROM 'authenticated' OR public.fn_izo_uid() IS NULL THEN
  RETURN jsonb_build_object('cod','fara_drept'); END IF;
 IF jsonb_typeof(p_ops) IS DISTINCT FROM 'array' OR jsonb_array_length(p_ops) NOT BETWEEN 1 AND 50 OR octet_length(p_ops::text)>262144 THEN
  RETURN jsonb_build_object('cod','limita'); END IF;
 v_uid:=public.fn_izo_uid();
 BEGIN
  v_pr:=(p_ops#>>'{0,payload,proiect_id}')::bigint; v_tr:=(p_ops#>>'{0,payload,tronson_id}')::bigint;
  IF v_pr IS NULL OR v_tr IS NULL OR p_dispozitiv IS NULL THEN RETURN jsonb_build_object('cod','eroare','motiv','lot_format'); END IF;
  FOR v_op IN SELECT value FROM jsonb_array_elements(p_ops) LOOP
   IF jsonb_typeof(v_op)<>'object' OR v_op-ARRAY['op_id','seq','tip_op','ora_tableta','payload','versiune_format']<>'{}'::jsonb
    OR (v_op#>>'{payload,proiect_id}')::bigint IS DISTINCT FROM v_pr OR (v_op#>>'{payload,tronson_id}')::bigint IS DISTINCT FROM v_tr
    OR (v_op->>'seq')::bigint IS NULL OR (v_op->>'seq')::bigint<=v_seq OR (v_op->>'op_id')::uuid IS NULL THEN
    RETURN jsonb_build_object('cod','eroare','motiv','lot_format'); END IF;
   v_seq:=(v_op->>'seq')::bigint;
  END LOOP;
 EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN jsonb_build_object('cod','eroare','motiv','lot_format'); END;
 v_code:=public.fn_izo_teren_entra(v_pr,'sync');
 IF v_code IS NOT NULL THEN RETURN jsonb_build_object('cod',v_code); END IF;
 SELECT * INTO v_f FROM public.izo_fronturi WHERE tronson_id=v_tr AND activ FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('cod','front_expirat'); END IF;
 IF v_f.proiect_id<>v_pr THEN RETURN jsonb_build_object('cod','fara_drept'); END IF;
 PERFORM 1 FROM public.izo_preverificari WHERE proiect_id=v_pr AND autor_profile_id=v_uid ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.izo_declaratii WHERE proiect_id=v_pr AND declarat_de=v_uid ORDER BY id FOR UPDATE;
 v_emp:=public.fn_izo_teren_autorizat(v_pr,true);
 IF v_emp IS NULL THEN RETURN jsonb_build_object('cod','fara_drept'); END IF;
 IF v_f.profile_id<>v_uid OR v_f.dispozitiv_id<>p_dispozitiv THEN
  FOR v_op IN SELECT value FROM jsonb_array_elements(p_ops) LOOP
   BEGIN
    v_p:=public.fn_izo_teren_payload(v_op->'payload');
    INSERT INTO public.izo_sync_incercari(proiect_id,tronson_id,autor_profile_id,op_id,dispozitiv_id,tip_op,payload)
     VALUES(v_pr,v_tr,v_uid,(v_op->>'op_id')::uuid,p_dispozitiv,v_op->>'tip_op',v_p) ON CONFLICT DO NOTHING;
   EXCEPTION WHEN SQLSTATE 'IZ001' THEN NULL; END;
   v_results:=v_results||jsonb_build_array(jsonb_build_object('op_id',v_op->>'op_id','cod','alt_dispozitiv'));
  END LOOP;
  RETURN jsonb_build_object('cod','alt_dispozitiv','rezultate',v_results);
 END IF;
 IF v_f.expira_la<=now() THEN RETURN jsonb_build_object('cod','front_expirat'); END IF;
 IF NOT EXISTS(SELECT 1 FROM public.izo_dispozitive WHERE dispozitiv_id=p_dispozitiv AND profile_id=v_uid) THEN RETURN jsonb_build_object('cod','fara_drept'); END IF;
 -- Conservative, fixed superset of the transitive closure: all this author's project rows.
 -- It also contains dependencies introduced by earlier operations in the same batch.
 PERFORM 1 FROM public.izo_tronson_config WHERE tronson_id=v_tr AND proiect_id=v_pr FOR SHARE;
 PERFORM public.fn_izo_blocheaza_locuri(v_pr,ARRAY(SELECT DISTINCT depozit_id FROM public.magazie_bucati WHERE proiect_id=v_pr AND depozit_id IS NOT NULL ORDER BY depozit_id),ARRAY[v_tr]);
 IF NOT EXISTS(SELECT 1 FROM public.izo_tronson_config WHERE tronson_id=v_tr AND proiect_id=v_pr AND flux_montaj)
  OR coalesce(public.fn_izo_nivel(v_pr),'off') NOT IN ('stoc','montaj') THEN RETURN jsonb_build_object('cod','fara_drept'); END IF;
 -- No project advisory: roots serialize reservation races across fronts (§10.5).
 PERFORM 1 FROM public.magazie_bucati WHERE proiect_id=v_pr AND tip_cod IS NOT NULL AND id=radacina_id ORDER BY id FOR UPDATE;
 PERFORM 1 FROM public.magazie_bucati WHERE proiect_id=v_pr AND tip_cod IS NOT NULL ORDER BY id FOR UPDATE;
 SELECT ultimul_seq INTO v_last FROM public.izo_dispozitive WHERE dispozitiv_id=p_dispozitiv FOR UPDATE;
 IF (SELECT count(*) FROM public.izo_operatii WHERE autor_profile_id=v_uid AND ora_server>now()-interval '1 hour')+jsonb_array_length(p_ops)>600 THEN
  RETURN jsonb_build_object('cod','limita'); END IF;
 FOR v_op IN SELECT value FROM jsonb_array_elements(p_ops) LOOP
  v_opid:=(v_op->>'op_id')::uuid; v_seq:=(v_op->>'seq')::bigint;
  v_format:=CASE WHEN coalesce(v_op->>'versiune_format','') ~ '^[0-9]{1,8}$' THEN (v_op->>'versiune_format')::integer ELSE 0 END;
  v_hash:=encode(sha256(convert_to(jsonb_build_object('dispozitiv_id',p_dispozitiv,'cerere',v_op)::text,'UTF8')),'hex');
  SELECT * INTO v_old FROM public.izo_operatii WHERE autor_profile_id=v_uid AND op_id=v_opid;
  IF FOUND THEN
   v_response:=CASE WHEN v_old.canal='teren' AND v_old.hash_cerere=v_hash
    THEN jsonb_build_object('cod','duplicat','raspuns',v_old.raspuns) ELSE jsonb_build_object('cod','conflict_op') END;
   v_results:=v_results||jsonb_build_array(jsonb_build_object('op_id',v_opid)||v_response); CONTINUE;
  END IF;
  v_response:=NULL; v_result:='acceptat'; v_code:=NULL; v_p:='{}'; v_ora:=NULL;
  BEGIN
   v_p:=public.fn_izo_teren_payload(v_op->'payload');
   v_ora:=(v_op->>'ora_tableta')::timestamptz;
   IF (v_p->>'depinde_de_uid')::uuid=ANY(v_deps) OR EXISTS(SELECT 1 FROM public.izo_declaratii
    WHERE uid=(v_p->>'depinde_de_uid')::uuid AND stare IN ('conflict','blocata')) THEN
    v_response:=jsonb_build_object('cod','blocat_de_conflict');
   ELSE
    IF v_op->>'tip_op'='decl_salveaza' AND (v_p->>'versiune_baza')::integer=0 AND
     ((SELECT count(*) FROM public.izo_rezervari WHERE autor_profile_id=v_uid AND activa AND (expira_dupa IS NULL OR expira_dupa>now()))>=60
     OR ((SELECT count(*) FROM public.izo_rezervari WHERE autor_profile_id=v_uid AND activa AND din_depozit AND (expira_dupa IS NULL OR expira_dupa>now()))>=10
      AND EXISTS(SELECT 1 FROM public.magazie_bucati WHERE id=coalesce((v_p#>>'{bucata,bucata_id}')::bigint,(v_p#>>'{sursa,bucata_id}')::bigint) AND depozit_id IS NOT NULL))) THEN
     v_response:=jsonb_build_object('cod','limita');
    ELSIF v_op->>'tip_op'='decl_salveaza' AND (v_p->>'versiune_baza')::integer=0 AND
     (SELECT count(*) FROM public.izo_declaratii d JOIN public.izo_preverificari s ON s.id=d.preverificare_id WHERE s.uid=(v_p->>'preverificare_uid')::uuid)>=200 THEN
     v_response:=jsonb_build_object('cod','limita');
    ELSE
     v_response:=public.fn_izo_teren_op(p_dispozitiv,v_op,v_p,v_emp,v_hash,v_f);
     v_response:=v_response||jsonb_build_object('alerte',to_jsonb(array_remove(ARRAY[
      CASE WHEN abs(extract(epoch FROM now()-v_ora))>300 THEN 'izo_ceas_tableta' END,
      CASE WHEN v_seq>v_last+1 THEN 'izo_gol_operatii' END],NULL)));
     -- Journal is the LAST write of this operation's savepoint.
     INSERT INTO public.izo_operatii(autor_profile_id,op_id,canal,proiect_id,tronson_id,dispozitiv_id,seq,versiune_format,tip_op,payload,hash_cerere,rezultat,raspuns,ora_tableta,offset_ceas_s)
      VALUES(v_uid,v_opid,'teren',v_pr,v_tr,p_dispozitiv,v_seq,v_format,v_op->>'tip_op',v_p,v_hash,'acceptat',v_response,v_ora,extract(epoch FROM now()-v_ora));
    END IF;
   END IF;
  EXCEPTION
   WHEN serialization_failure OR deadlock_detected OR lock_not_available OR query_canceled THEN
    v_response:=jsonb_build_object('cod','reincearca'); v_stop:=true;
   WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_state=RETURNED_SQLSTATE;
    IF v_state='IZ003' THEN v_response:=jsonb_build_object('cod','blocat_de_conflict');
    ELSE
     v_result:=CASE WHEN v_state IN ('IZ002','23505') THEN 'conflict' WHEN left(v_state,2) IN ('IZ','22','23') THEN 'eroare' ELSE 'eroare_interna' END;
     -- Do not copy SQLERRM from arbitrary SQL: it can include submitted GPS values.
     v_code:=CASE WHEN left(v_state,2)='IZ' THEN SQLERRM ELSE v_state END;
     v_response:=jsonb_build_object('cod',v_result,'motiv',v_code);
     INSERT INTO public.izo_operatii(autor_profile_id,op_id,canal,proiect_id,tronson_id,dispozitiv_id,seq,versiune_format,tip_op,payload,hash_cerere,rezultat,cod,raspuns,ora_tableta)
      VALUES(v_uid,v_opid,'teren',v_pr,v_tr,p_dispozitiv,v_seq,v_format,coalesce(v_op->>'tip_op',''),v_p,v_hash,v_result,v_code,v_response,v_ora);
    END IF;
  END;
  IF v_response->>'cod'<>'acceptat' OR v_response->>'stare' IN ('conflict','blocata') THEN
   BEGIN v_deps:=array_append(v_deps,(v_p->>'uid')::uuid); EXCEPTION WHEN invalid_text_representation THEN NULL; END;
  END IF;
  v_results:=v_results||jsonb_build_array(jsonb_build_object('op_id',v_opid)||v_response);
  IF v_stop THEN EXIT; END IF;
  v_last:=greatest(v_last,v_seq);
 END LOOP;
 UPDATE public.izo_dispozitive SET ultimul_seq=v_last,server_ver=nextval('public.izo_server_ver_seq') WHERE dispozitiv_id=p_dispozitiv AND profile_id=v_uid;
 RETURN jsonb_build_object('cod','ok','rezultate',v_results,'server_ver_max',greatest(
  coalesce((SELECT max(server_ver) FROM public.izo_declaratii WHERE proiect_id=v_pr),0),
  coalesce((SELECT max(server_ver) FROM public.izo_rezervari WHERE proiect_id=v_pr),0)));
END $f$;
  CREATE FUNCTION public.fn_izo_sync_push(p_dispozitiv uuid,p_ops jsonb) RETURNS jsonb
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT public.fn_izo_teren_push(p_dispozitiv,p_ops)
$f$;

  CREATE FUNCTION public.fn_izo_gps_citeste(p_decl bigint) RETURNS jsonb
 LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
DECLARE v_pr bigint; v_uid uuid; v_result jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'READ COMMITTED' USING ERRCODE='25001'; END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtext('gazpet.livrare_migrare'));
 IF session_user<>'authenticator' OR public.fn_izo_jwt_rol() IS DISTINCT FROM 'authenticated' THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
 v_uid:=public.fn_izo_uid();
 SELECT proiect_id INTO v_pr FROM public.izo_declaratii WHERE id=p_decl;
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=v_uid AND employee_id IS NOT NULL AND (is_owner OR
  EXISTS(SELECT 1 FROM public.izo_atribuiri WHERE profile_id=v_uid AND proiect_id=v_pr AND activ AND rol IN ('manager_aprobator','inlocuitor_aprobator')
   AND current_date BETWEEN valabil_de AND coalesce(valabil_pana,current_date)))) THEN RAISE EXCEPTION 'fara_drept' USING ERRCODE='42501'; END IF;
 IF cardinality(public.fn_izo_porti_lipsa())<>0 THEN RAISE EXCEPTION 'E4b porti'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(g) ORDER BY versiune),'[]'::jsonb) INTO v_result FROM public.izo_declaratii_gps g WHERE declaratie_id=p_decl;
 RETURN v_result;
END $f$;
  CREATE FUNCTION public.fn_izo_teren_pregateste(p_proiect bigint,p_tronson bigint,p_dispozitiv uuid) RETURNS jsonb
 LANGUAGE sql SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 SELECT public.fn_izo_teren_intern(p_proiect,p_tronson,p_dispozitiv,true)
$f$;

 REVOKE ALL ON FUNCTION public.fn_izo_teren_imuabil() FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_izo_teren_autorizat(bigint,boolean) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_izo_teren_entra(bigint,text) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_izo_pv_lipsa(bigint[]) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_izo_teren_snapshot(bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_izo_teren_intern(bigint,bigint,uuid,boolean) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_izo_teren_instantaneu(bigint,bigint) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_izo_teren_payload(jsonb) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_izo_teren_op(uuid,jsonb,jsonb,bigint,text,public.izo_fronturi) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_izo_teren_push(uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_izo_sync_push(uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_izo_gps_citeste(bigint) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.fn_izo_teren_pregateste(bigint,bigint,uuid) FROM PUBLIC,anon,authenticated,service_role;
 -- NOLOGIN role has no direct write route. Private, typed helpers hold postgres privileges.
 -- API wrappers carry no setters, dynamic SQL, or identity text (control_0e).
 GRANT EXECUTE ON FUNCTION public.fn_izo_teren_intern(bigint,bigint,uuid,boolean),public.fn_izo_teren_push(uuid,jsonb) TO izo_teren_editor;
 GRANT EXECUTE ON FUNCTION public.fn_izo_pv_lipsa(bigint[]) TO izo_teren_editor,izo_montaj_writer;
 GRANT CREATE ON SCHEMA public TO izo_teren_editor;
 ALTER FUNCTION public.fn_izo_teren_instantaneu(bigint,bigint) OWNER TO izo_teren_editor;
 ALTER FUNCTION public.fn_izo_teren_pregateste(bigint,bigint,uuid) OWNER TO izo_teren_editor;
 ALTER FUNCTION public.fn_izo_sync_push(uuid,jsonb) OWNER TO izo_teren_editor;
 REVOKE CREATE ON SCHEMA public FROM izo_teren_editor;
 SET LOCAL ROLE izo_teren_editor;
 GRANT EXECUTE ON FUNCTION public.fn_izo_teren_instantaneu(bigint,bigint),public.fn_izo_teren_pregateste(bigint,bigint,uuid),public.fn_izo_sync_push(uuid,jsonb) TO authenticated;
 RESET ROLE;
 GRANT EXECUTE ON FUNCTION public.fn_izo_gps_citeste(bigint) TO authenticated;
 CREATE VIEW public.v_izo_carantina_sync WITH (security_invoker=on) AS
  SELECT i.* FROM public.izo_sync_incercari i WHERE NOT EXISTS(SELECT 1 FROM public.izo_operatii o WHERE o.autor_profile_id=i.autor_profile_id AND o.op_id=i.op_id);
 CREATE VIEW public.v_izo_rezervari_active WITH (security_invoker=on) AS
  SELECT * FROM public.izo_rezervari WHERE activa AND (expira_dupa IS NULL OR expira_dupa>now());
 REVOKE ALL ON public.v_izo_carantina_sync,public.v_izo_rezervari_active FROM PUBLIC,anon,authenticated,service_role;
 GRANT SELECT ON public.v_izo_carantina_sync,public.v_izo_rezervari_active TO authenticated;

 CREATE FUNCTION public.fn_izo_porti_e4b_definitii() RETURNS text
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  SELECT md5(concat_ws('|',
   (SELECT string_agg(format('%s:%s:%s:%s:%s:%s',p.oid::regprocedure,p.proowner,p.prosecdef,p.proconfig,p.proacl,md5(p.prosrc)),',' ORDER BY p.oid::regprocedure::text)
    FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname LIKE 'fn\_izo\_%'),
   (SELECT string_agg(format('%s:%s:%s:%s:%s',c.relname,c.relowner,c.relrowsecurity,c.relacl,c.reloptions),',' ORDER BY c.relname)
    FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND (c.relname=ANY(ARRAY['izo_fronturi', 'izo_dispozitive', 'izo_preverificari', 'izo_declaratii', 'izo_bucati_declarate', 'izo_rezervari', 'izo_operatii', 'izo_declaratii_versiuni', 'izo_declaratii_gps', 'izo_sync_incercari', 'izo_rata_apeluri']::text[]) OR c.relname IN ('v_izo_carantina_sync','v_izo_rezervari_active'))),
   (SELECT string_agg(format('%s:%s:%s:%s:%s:%s',c.relname,a.attname,a.atttypid,a.attnotnull,a.attacl,pg_get_expr(d.adbin,d.adrelid)),',' ORDER BY c.relname,a.attnum)
    FROM pg_class c JOIN pg_attribute a ON a.attrelid=c.oid LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum
    WHERE c.relnamespace='public'::regnamespace AND c.relname=ANY(ARRAY['izo_fronturi', 'izo_dispozitive', 'izo_preverificari', 'izo_declaratii', 'izo_bucati_declarate', 'izo_rezervari', 'izo_operatii', 'izo_declaratii_versiuni', 'izo_declaratii_gps', 'izo_sync_incercari', 'izo_rata_apeluri']::text[]) AND a.attnum>0 AND NOT a.attisdropped),
   (SELECT string_agg(format('%s:%s',c.relname,pg_get_constraintdef(k.oid)),',' ORDER BY c.relname,k.conname)
    FROM pg_class c JOIN pg_constraint k ON k.conrelid=c.oid WHERE c.relnamespace='public'::regnamespace AND c.relname=ANY(ARRAY['izo_fronturi', 'izo_dispozitive', 'izo_preverificari', 'izo_declaratii', 'izo_bucati_declarate', 'izo_rezervari', 'izo_operatii', 'izo_declaratii_versiuni', 'izo_declaratii_gps', 'izo_sync_incercari', 'izo_rata_apeluri']::text[])),
   (SELECT string_agg(format('%s:%s:%s:%s:%s:%s',c.relname,p.polname,p.polcmd,p.polroles,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)),',' ORDER BY c.relname,p.polname)
    FROM pg_class c JOIN pg_policy p ON p.polrelid=c.oid WHERE c.relnamespace='public'::regnamespace AND c.relname=ANY(ARRAY['izo_fronturi', 'izo_dispozitive', 'izo_preverificari', 'izo_declaratii', 'izo_bucati_declarate', 'izo_rezervari', 'izo_operatii', 'izo_declaratii_versiuni', 'izo_declaratii_gps', 'izo_sync_incercari', 'izo_rata_apeluri']::text[])),
   (SELECT string_agg(format('%s:%s:%s',c.relname,pg_get_triggerdef(g.oid),g.tgenabled),',' ORDER BY c.relname,g.tgname)
    FROM pg_class c JOIN pg_trigger g ON g.tgrelid=c.oid WHERE c.relnamespace='public'::regnamespace AND c.relname=ANY(ARRAY['izo_fronturi', 'izo_dispozitive', 'izo_preverificari', 'izo_declaratii', 'izo_bucati_declarate', 'izo_rezervari', 'izo_operatii', 'izo_declaratii_versiuni', 'izo_declaratii_gps', 'izo_sync_incercari', 'izo_rata_apeluri']::text[]) AND NOT g.tgisinternal),
   (SELECT string_agg(pg_get_indexdef(i.indexrelid),',' ORDER BY i.indexrelid::regclass::text)
    FROM pg_class c JOIN pg_index i ON i.indrelid=c.oid WHERE c.relnamespace='public'::regnamespace AND c.relname=ANY(ARRAY['izo_fronturi', 'izo_dispozitive', 'izo_preverificari', 'izo_declaratii', 'izo_bucati_declarate', 'izo_rezervari', 'izo_operatii', 'izo_declaratii_versiuni', 'izo_declaratii_gps', 'izo_sync_incercari', 'izo_rata_apeluri']::text[])),
   (SELECT string_agg(format('%s:%s:%s',c.relname,c.relowner,c.relacl),',' ORDER BY c.relname) FROM pg_class c
    WHERE c.relnamespace='public'::regnamespace AND c.relkind='S' AND (c.relname LIKE 'izo\_fronturi\_%' OR c.relname LIKE 'izo\_preverificari\_%' OR c.relname LIKE 'izo\_declaratii\_%' OR c.relname LIKE 'izo\_rezervari\_%' OR c.relname LIKE 'izo\_operatii\_%' OR c.relname LIKE 'izo\_sync\_incercari\_%')),
   (SELECT concat_ws(':',rolcanlogin,rolinherit,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls,rolconfig) FROM pg_roles WHERE rolname='izo_teren_editor'),
   (SELECT string_agg(format('%s:%s:%s:%s:%s',roleid,member,admin_option,inherit_option,set_option),',' ORDER BY roleid,member) FROM pg_auth_members WHERE roleid='izo_teren_editor'::regrole OR member='izo_teren_editor'::regrole)))
 $f$;
 CREATE FUNCTION public.fn_izo_porti_e4b_lipsa() RETURNS text[]
  LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
 BEGIN
  IF public.fn_izo_porti_e4b_definitii() IS DISTINCT FROM substring(obj_description('public.fn_izo_porti_e4b_definitii()'::regprocedure,'pg_proc') FROM '^porti_e4b=([0-9a-f]{32})$') THEN RETURN ARRAY['E4b definitii diferite']; END IF;
  RETURN '{}'::text[];
 END $f$;
 REVOKE ALL ON FUNCTION public.fn_izo_porti_e4b_definitii(),public.fn_izo_porti_e4b_lipsa() FROM PUBLIC,anon,authenticated,service_role;
   CREATE OR REPLACE FUNCTION public.fn_izo_porti_lipsa() RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public, pg_temp AS $f$
  DECLARE v text[] := '{}'; r record;
  BEGIN
    -- triggerele: există și sunt ENABLE ALWAYS ('A' — trag și sub session_replication_role = replica)
    FOR r IN SELECT x.tabel, x.trg, g.tgenabled
               FROM (VALUES ('magazie_bucati','trg_magbuc_izo_garda'), ('magazie_bucati','trg_magbuc_izo_truncate'),
                            ('magazie_bucati_evenimente','trg_izo_ev_garda'), ('magazie_bucati_evenimente','trg_izo_ev_truncate'),
                            ('magazie_bucati_miscari','trg_izo_mis_garda'), ('magazie_bucati_miscari','trg_izo_mis_truncate'),
                            ('izo_importuri','trg_izo_imp_garda'), ('izo_importuri','trg_izo_imp_truncate'),
                            ('izo_proiect_config','trg_izo_cfg_garda'), ('izo_proiect_config','trg_izo_cfg_truncate'),
                            ('izo_atribuiri','trg_izo_atr_garda'), ('izo_atribuiri','trg_izo_atr_truncate'),
                            ('executie_tevi','trg_executie_tevi_izo_delete'), ('executie_tevi','trg_executie_tevi_izo_mutare'),
                            ('executie_pachete_lansare','trg_pachete_izo_delete'), ('executie_pachete_lansare','trg_pachete_izo_mutare'),
                            ('executie_tronsoane','trg_tronsoane_izo_mutare'), ('logistica_depozite','trg_depozite_izo_mutare'),
                            ('executie_proiecte','trg_proiecte_izo_site'),
                            ('executie_tevi','trg_executie_tevi_izo_truncate'), ('executie_pachete_lansare','trg_pachete_izo_truncate'),
                            ('executie_bonuri_consum_linii','trg_bon_linii_izo_bucata')) x(tabel, trg)
               LEFT JOIN pg_trigger g ON g.tgname = x.trg AND g.tgrelid = to_regclass('public.' || x.tabel) AND NOT g.tgisinternal
    LOOP
      IF r.tgenabled IS DISTINCT FROM 'A' THEN v := array_append(v, format('trigger %s.%s (%s)', r.tabel, r.trg, coalesce(r.tgenabled::text, 'lipsă'))); END IF;
    END LOOP;
    -- RLS activ pe tabelele registrului și pe magazie_bucati
    FOR r IN SELECT t.n, c.relrowsecurity FROM unnest(ARRAY['magazie_bucati','izo_proiect_config','izo_atribuiri','izo_importuri',
                      'magazie_bucati_evenimente','magazie_bucati_miscari']) t(n) LEFT JOIN pg_class c ON c.oid = to_regclass('public.' || t.n)
    LOOP
      IF r.relrowsecurity IS NOT TRUE THEN v := array_append(v, format('RLS inactiv pe %s', r.n)); END IF;
    END LOOP;
    -- politicile RESTRICTIVE ale clientului pe magazie_bucati
    IF (SELECT count(*) FROM pg_policy p WHERE p.polrelid = 'public.magazie_bucati'::regclass AND NOT p.polpermissive
          AND p.polname IN ('magbuc_izo_client_sel','magbuc_izo_client_ins','magbuc_izo_client_upd','magbuc_izo_client_del')) <> 4 THEN
      v := array_append(v, 'politicile RESTRICTIVE magbuc_izo_client_*');
    END IF;
    -- rolul scriitor: fără BYPASSRLS/LOGIN/SUPERUSER/INHERIT; singurul membru = postgres; niciun rol API nu-l poate prelua
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'izo_registru_writer' AND NOT rolbypassrls AND NOT rolcanlogin AND NOT rolsuper AND NOT rolinherit) THEN
      v := array_append(v, 'rolul izo_registru_writer (lipsă sau BYPASSRLS/LOGIN/SUPERUSER/INHERIT)');
    -- membri: doar postgres (PG16+: CREATE ROLE de către un non-superuser adaugă automat un rând ADMIN fără SET/INHERIT,
    -- grantor = superuser-ul de bootstrap — pe Supabase supabase_admin; găsit de testul pe branch PG17); SET da, INHERIT nu
    ELSIF EXISTS (SELECT 1 FROM pg_auth_members m WHERE m.roleid = 'izo_registru_writer'::regrole AND m.member <> 'postgres'::regrole)
       OR NOT EXISTS (SELECT 1 FROM pg_auth_members m WHERE m.roleid = 'izo_registru_writer'::regrole AND m.member = 'postgres'::regrole AND m.set_option)
       OR EXISTS (SELECT 1 FROM pg_auth_members m WHERE m.roleid = 'izo_registru_writer'::regrole AND m.inherit_option)
       OR EXISTS (SELECT 1 FROM unnest(ARRAY['anon','authenticated','service_role','authenticator']) a(n)
                   WHERE EXISTS (SELECT 1 FROM pg_roles WHERE rolname = a.n) AND pg_has_role(a.n, 'izo_registru_writer', 'MEMBER')) THEN
      v := array_append(v, 'membrii rolului izo_registru_writer');
    END IF;
    -- ACL: clientul nu scrie tabelele registrului și nu execută funcțiile writer-ului
    IF EXISTS (SELECT 1 FROM unnest(ARRAY['izo_proiect_config','izo_atribuiri','izo_importuri','magazie_bucati_evenimente','magazie_bucati_miscari']) t(n),
                             unnest(ARRAY['anon','authenticated','service_role']) a(n), unnest(ARRAY['INSERT','UPDATE','DELETE','TRUNCATE']) p(n)
                WHERE to_regclass('public.' || t.n) IS NULL OR has_table_privilege(a.n, 'public.' || t.n, p.n)) THEN
      v := array_append(v, 'ACL de scriere pe tabelele registrului');
    END IF;
    IF EXISTS (SELECT 1 FROM pg_proc p, unnest(ARRAY['anon','authenticated','service_role']) a(n)
                WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('fn_izo_seteaza_nivel','fn_izo_import_sold_initial','fn_izo_import_storno','fn_izo_activeaza_si_importa')
                  AND has_function_privilege(a.n, p.oid, 'EXECUTE')) THEN
      v := array_append(v, 'EXECUTE din API pe funcțiile registrului');
    END IF;
    -- allowlist pe ACL (invariantul principal, Copilot r6 c): intrările writer-ului se execută DOAR de owner și postgres
    IF EXISTS (SELECT 1 FROM pg_proc p, aclexplode(coalesce(p.proacl, acldefault('f', p.proowner))) a
                WHERE p.pronamespace = 'public'::regnamespace
                  AND p.proname IN ('fn_izo_seteaza_nivel','fn_izo_import_sold_initial','fn_izo_import_storno','fn_izo_activeaza_si_importa')
                  AND a.privilege_type = 'EXECUTE' AND (a.grantee = 0 OR pg_get_userbyid(a.grantee) NOT IN ('izo_registru_writer','postgres'))) THEN
      v := array_append(v, 'EXECUTE pe funcțiile registrului pentru alt rol decât writer / postgres (allowlist)');
    END IF;
    -- wrapper-e (plasă de siguranță peste allowlist): o funcție cu alt owner decât writer-ul sau un view / o regulă care cheamă funcțiile registrului ar
    -- deveni o cale nouă spre ele (Codex r5 6) — acceptate doar după review, cu actualizarea acestei porți
    IF EXISTS (SELECT 1 FROM pg_proc p WHERE p.proowner <> 'izo_registru_writer'::regrole
                AND p.oid <> 'public.fn_izo_porti_lipsa()'::regprocedure   -- poarta însăși le numește în verificarea ACL
                -- corpul complet: prosrc (plpgsql / sql clasic) + corpul BEGIN ATOMIC (prosrc gol, corpul în prosqlbody) — review r7
                AND (p.prosrc || ' ' || coalesce(pg_get_function_sqlbody(p.oid), ''))
                    ~* 'fn_izo_(seteaza_nivel|import_sold_initial|import_storno|activeaza_si_importa)')   -- fără majuscule (N3)
       OR EXISTS (SELECT 1 FROM pg_rewrite rw WHERE pg_get_ruledef(rw.oid) ~* 'fn_izo_(seteaza_nivel|import_sold_initial|import_storno|activeaza_si_importa)') THEN
      v := array_append(v, 'o funcție / un view din afara writer-ului cheamă funcțiile registrului (wrapper nerevizuit)');
    END IF;
    -- CITIRILE (acțiunea 6, Codex r4 / Jakarinos r6–r10): filtrarea citirii (RLS restrictiv + fn_izo_citire) se poate ocoli
    -- fără niciun trigger de scriere printr-un view cu drepturile ownerului sau printr-o funcție DEFINER care întoarce rânduri.
    -- Inventarul de pe live (docs/izometrie/E2A_INVENTAR_CITIRI.md, 21.10.2026): 0 view-uri, 0 funcții care ating
    -- magazie_bucati, 5 DEFINER cu SQL dinamic pe tabele fixe (profiles / executie_proiecte), neexpuse. Porțile de mai jos
    -- refuză activarea dacă apare ceva nou, nerevizuit (r11: porți pe tipuri; r12: închiderea tranzitivă de mai jos):
    -- r12 (Jakarinos + Copilot r11): ÎNCHIDEREA TRANZITIVĂ a tot ce poate citi registrul, până la punct fix:
    --   sămânța = tabelele registrului + funcțiile cu SQL dinamic (pot citi orice tabel) din afara listei revizuite;
    --   se adaugă repetat: view-urile / view-urile materializate care depind (pg_depend → pg_rewrite) de ceva din închidere
    --   (inclusiv cele security_invoker — un DEFINER care le citește le ocolește RLS-ul), și funcțiile (orice schemă
    --   non-sistem, în afara public.fn_izo_*) al căror corp NUMEȘTE ceva din închidere (în public: numele simplu; în alte
    --   scheme: schema.nume) sau depind de el în catalog (corpuri BEGIN ATOMIC).
    -- Refuz dacă în închidere apare: un view fără security_invoker, un view materializat sau o funcție SECURITY DEFINER.
    -- Funcțiile DEFINER cu SQL dinamic din afara listei revizuite sunt refuzate oricum (citesc orice, fără să numească).
    DECLARE
      c_rel oid[]; c_fn oid[] := '{}'; v_marime int := -1; v_iter int := 0; c_mut oid[] := '{}';
      -- funcțiile DEFINER cu SQL dinamic revizuite pe live (docs/izometrie/E2A_INVENTAR_CITIRI.md, 21.10.2026): tabele fixe
      -- (executie_proiecte / profiles), identificatori pe listă albă. Amprenta excepției = md5(prosrc | proconfig | owner |
      -- proacl | prosecdef) (Jakarinos r12): orice schimbare de corp, search_path, owner sau drepturi cere review
      c_dinamice_revizuite text[] := ARRAY[
        '_completare_goleste_camp(bigint,text,integer)=888fde4d4e7fbea6889835dd96c2225d',
        '_completare_scrie_camp(bigint,text,text)=77d7b091a049ccc86b47d078957db39f',
        'fn_cont_inchide(uuid,text,text,integer)=c4a6ca93a52ca8a97aa90f168debf30e',
        'fn_cont_restaureaza_flaguri(uuid,jsonb)=ecd803a2dda6b734ea92ebaf10564397',
        'fn_conturi_inchideri_sweep()=402874ea5081b41801313e0def9e3226',
        'fn_tichete_notif_on_insert()=1ffa41a8750b6d48d721d9e2a00b3f54'];
      -- limitele unui identificator, inclusiv citat („"teste".f()”), fără \m / \M (ghilimelele nu sunt caractere de cuvânt)
      c_st constant text := '(^|[^[:alnum:]_$"])"?';
      c_dr constant text := '"?($|[^[:alnum:]_$])';
      -- schemele platformei Supabase: obiectele lor din închidere (funcții INVOKER cu SQL dinamic: realtime.cast, storage.search…)
      -- se potrivesc necalificat DOAR când schema e în search_path-ul funcției; ale noastre (orice altă schemă) se potrivesc
      -- necalificat ÎNTOTDEAUNA — conservator, fals-pozitivele sunt acceptate (Copilot r12 P1)
      c_scheme_platforma constant text[] := ARRAY['auth','storage','realtime','extensions','graphql','graphql_public','vault','net',
                                                  'supabase_functions','supabase_migrations','pgbouncer','pgsodium','pgsodium_masks','cron'];
      -- r5d (20261103b): aceeași semantică, evaluare SEMI-NAIVĂ — fiecare element nou al închiderii se caută o singură dată,
      -- cu alternanța numelor din frontieră (r5f: pe bucăți mărginite, nu o singură expresie); corpurile se citesc o dată
      k_oid oid[]; k_corp text[]; k_cale text[]; f_rel oid[]; f_fn oid[]; f_mut oid[]; n_rel oid[]; n_fn oid[]; n_mut oid[];
      -- r5f (#825 NO-GO): tiparele frontierei, pe bucăți: a_x = alternanța (≤ ~4000 de caractere), a_s = schema de platformă
      -- căreia i se aplică (NULL = oricărei funcții)
      a_s text[]; a_x text[];
      k_i int; k_n int; k_s text; k_s2 text; k_adanc oid[] := '{}';
      -- r5g (#825) NO-GO P2: o schemă a platformei urmată (după ghilimele / spații / un punct opțional) de deschiderea unui
      -- comentariu — singura formă în care un comentariu rupe apelul ei calificat
      k_com text := c_st || '(' || array_to_string(c_scheme_platforma, '|') || ')"?[[:space:]]*(\.[[:space:]]*)?(/\*|--)';
      -- r5g (#825) NO-GO P1-D: invocările implicite revizuite, de pe prod — singurele obiecte din catalog care cheamă implicit o
      -- funcție din închiderea de pe prod sau (r5h) un mutator de cale; citite read-only 22.10.2026 (baseline_pre_e3.json, cheia
      -- „implicite”). r5h (#825 r5g NO-GO, Jak P1): amprenta = md5(tip | identitate | funcția | owner | SECURITY DEFINER |
      -- proconfig | limbaj | md5(corp)) — CU corpul: un corp schimbat (același owner / config) nu mai păstrează excepția. Un
      -- upgrade Supabase care schimbă corpul uneia dintre funcțiile de platformă înroșește poarta (fail-closed): captură nouă
      -- + review + migrare (design §17)
      c_implicite_revizuite constant text[] := ARRAY[
        'event trigger issue_graphql_placeholder=2aa685a004bc87f7a10ef72d134a88bb',
        'event trigger issue_pg_graphql_access=7ed4741489f49636791f930411cfb345',
        'event trigger issue_pg_net_access=d62f8ab601b809080c679266fbdb8a06',
        'trigger a01_ofertare_cantitati_lot_canonic on public.ofertare_cantitati=62d07782ee60e73b327be8c82d4dd34b',
        'trigger a01_ofertare_cerinte_lot_canonic on public.ofertare_cerinte=b2b9b1f753fae9e4f8a7a10ee6c6b351',
        'trigger on_auth_user_created on auth.users=5f3f59717d56d1148ac3f4b7d3a2b199',
        'trigger prevent_role_escalation_trigger on public.profiles=06b7e4fcaab58c9a3faecb7ff4856b45',
        'trigger tr_check_filters on realtime.subscription=ed76f4ff4e3c6abd998eded3d159d3c3',
        'trigger trg_employees_persoana_lock on public.employees=9dcecd0c70efdf1bf5e24e9c1157bc11',
        'trigger trg_employees_zz_ciclu_cont on public.employees=8b5dbbd69476106544cff2b5393c116a',
        'trigger trg_enforce_owner_only_salary_flags on public.profiles=46f1b6af2f30d56993ca988b267e76d8',
        'trigger trg_hr_autorizatii_rsvti_doar_rpc on public.hr_autorizatii=9a7f49627ab4e62e14aa43252a2ab56e',
        'trigger trg_hr_employees_private_persoana_lock on public.hr_employees_private=32261dc19c5d0da91f0487ab2f33bb08',
        'trigger trg_profiles_campuri_owner_only on public.profiles=e80a3aed6ff3f2055785bdc974702cd5',
        'trigger trg_protect_can_access_pontaj_brut on public.profiles=3a58112eec4c06bef2d66159ad6f82a5'];
    BEGIN
      SELECT array_agg(c.oid) INTO c_rel FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace
         AND c.relname IN ('magazie_bucati','izo_proiect_config','izo_atribuiri','izo_importuri','magazie_bucati_evenimente','magazie_bucati_miscari');
      -- funcțiile cu SQL dinamic (orice EXECUTE), în afara registrului și a listei revizuite: în închidere de la început
      SELECT coalesce(array_agg(p.oid), '{}') INTO c_fn FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname !~ '^pg_' AND p.prolang NOT IN (12, 13)
         AND NOT (n.nspname = 'public' AND p.proname LIKE 'fn\_izo\_%')
         AND (p.prosrc || ' ' || coalesce(pg_get_function_sqlbody(p.oid), '')) ~* '\mexecute\M'
         AND format('%s=%s', p.oid::regprocedure::text, md5(p.prosrc || '|' || coalesce(p.proconfig::text, '') || '|' || pg_get_userbyid(p.proowner)
                                                           || '|' || coalesce(p.proacl::text, '') || '|' || p.prosecdef::text))
             <> ALL (c_dinamice_revizuite);
      -- r5f (#825): + tabelele documentelor E3 — RLS cu citire prin fn_izo_citire, ca registrul (design §13.2): un DEFINER /
      -- un view fără security_invoker / un lanț din afara fn_izo_* care ajunge la ele e refuzat la fel. Funcțiile E3 legitime
      -- (fn_izo_doc_* / fn_izo_scan_*, owner izo_doc_editor / izo_receptie_writer / postgres) sunt fn_izo_*: în afara
      -- închiderii, ca la E2a, și acoperite de ștampila E2a (fn_izo_porti_definitii: owner, corp, config, ACL)
      c_rel := c_rel || ARRAY(SELECT c.oid FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace
         AND c.relname IN ('izo_documente_intrare','izo_documente_intrare_randuri','izo_documente_scanuri'));
      -- r5g (#825) NO-GO P1-C: + TOATE funcțiile public.fn_izo_* ca ȚINTE (nu candidați): cititorii INVOKER ai documentelor
      -- (owner postgres) și DEFINER-ele interne citesc ce RLS-ul ascunde; un DEFINER / view / lanț din afara fn_izo_* care le
      -- cheamă (după nume, BEGIN ATOMIC, view, operator / cast / agregat) intră în închidere, ca un cititor direct. După
      -- propagare ele ies din c_fn (mai jos): sunt API-ul revizuit, sub ștampila E2a. Invocările lor implicite din catalog
      -- (trigger / politică / DEFAULT / CHECK …) sunt fixate de ștampila E3 (fn_izo_porti_e3_definitii)
      c_fn := c_fn || ARRAY(SELECT p.oid FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname LIKE 'fn\_izo\_%');
      -- corpurile candidate (orice schemă non-sistem, în afara public.fn_izo_*), o singură dată; calea fixată în proconfig
      -- (NULL = necunoscută: funcția moștenește calea apelantului)
      SELECT coalesce(array_agg(p.oid ORDER BY p.oid), '{}'),
             coalesce(array_agg(p.prosrc || ' ' || coalesce(pg_get_function_sqlbody(p.oid), '') ORDER BY p.oid), '{}'),
             coalesce(array_agg((SELECT array_to_string(string_to_array(lower(regexp_replace(substr(c, 13), '[[:space:]"]', '', 'g')), ','), ',')
                                   FROM unnest(p.proconfig) c WHERE c LIKE 'search\_path=%' LIMIT 1) ORDER BY p.oid), '{}')
        INTO k_oid, k_corp, k_cale
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname NOT IN ('pg_catalog', 'information_schema') AND n.nspname !~ '^pg_' AND p.prolang NOT IN (12, 13)
         AND NOT (n.nspname = 'public' AND p.proname LIKE 'fn\_izo\_%');
      -- r5f (#825 NO-GO): un comentariu între schemă și nume („storage/**/.f()”, „storage -- x⏎.f()”) ascunde forma calificată —
      -- contează la schemele platformei, unde necalificatul cere calea. Corpului i se adaugă o copie fără comentarii (blocurile
      -- imbricate din interior spre exterior, până la punct fix; apoi „--” până la capăt de rând). Copia doar ADAUGĂ potriviri
      -- (originalul rămâne): un „/*” sau „--” dintr-un șir taie din copie, nu din original. Cel mult 20 de niveluri (fiecare nivel
      -- = o trecere peste tot corpul — fără plafon, mii de comentarii imbricate ar ține poarta minute întregi): mai adânc → corpul
      -- nu se poate citi sigur, intră în sămânță ca SQL-ul dinamic (k_adanc, mai jos)
      -- r5g (#825, Copilot P1): copia nu înțelege literalii — un „--” / „/*” dintr-un șir taie din copie chiar apelul ascuns
      -- de comentariu („x := '--'; PERFORM storage /* c */ . f();”), iar originalul nu-l are calificat. Fail-closed, fără
      -- tokenizer: calea devine NECUNOSCUTĂ (NULL, în ambele bucle) și numele schemei se potrivesc în corp necalificat.
      -- r5g (#825) NO-GO P2: nu la orice „/*” / „--” (pe prod: 192 de corpuri, 162 DEFINER — un comentariu + „CAST(” /
      -- „send” / „search” ar fi înroșit poarta), ci doar când o schemă a platformei e urmată de deschiderea unui comentariu
      -- (k_com), pe ORIGINAL: comentariul care rupe apelul apare textual acolo, deci un literal nu-l poate ascunde; pe prod: 0
      -- corpuri. La celelalte scheme necalificatul se potrivește oricum, deci forma calificată ruptă nu ascunde nimic
      FOR k_i IN 1 .. cardinality(k_corp) LOOP
        IF k_corp[k_i] ~* k_com THEN k_cale[k_i] := NULL; END IF;
        k_s := k_corp[k_i]; k_n := 0;
        LOOP
          k_s2 := regexp_replace(k_s, '/\*([^*/]|\*+[^*/]|/+[^*/])*\*+/', ' ', 'g');
          EXIT WHEN k_s2 = k_s;
          k_s := k_s2; k_n := k_n + 1;
          IF k_n >= 20 THEN k_adanc := k_adanc || k_oid[k_i]; EXIT; END IF;
        END LOOP;
        k_s := regexp_replace(k_s, '--[^\n]*', ' ', 'g');
        IF k_s <> k_corp[k_i] THEN k_corp[k_i] := k_corp[k_i] || ' ' || k_s; END IF;
      END LOOP;
      -- r5f (#825 NO-GO): în sămânță și funcțiile care pot citi un tabel FĂRĂ să-i scrie numele și fără EXECUTE — identificatori
      -- U&"…" (escape-uri Unicode), SQL dat ca text (query/table/schema/database_to_xml, ts_stat / ts_rewrite, crosstab /
      -- connectby, dblink), fișierele / paginile tabelelor (pg_read_[binary_]file, lo_import, get_raw_page); ca SQL-ul
      -- dinamic: un DEFINER care le conține (sau le cheamă) e refuzat. Mai strict decât E2a, care le lasă verzi. Tot aici:
      -- corpurile cu comentarii imbricate peste plafon (k_adanc)
      c_fn := c_fn || ARRAY(SELECT k.oid FROM unnest(k_oid, k_corp) k(oid, corp) WHERE k.oid <> ALL (c_fn)
                              AND (k.oid = ANY (k_adanc)
                                   OR k.corp ~* ('u&"|\m(query|table|schema|database)_to_xml|\mts_(stat|rewrite)\M|\m(crosstab|connectby|dblink)'
                                                 || '|\mpg_read_(binary_)?file\M|\mlo_import\M|\mget_raw_page\M')));
      -- mutatorii de cale (r15): sămânța = corp cu set_config / search_path; propagați până la punct fix
      SELECT coalesce(array_agg(k.oid), '{}') INTO c_mut FROM unnest(k_oid, k_corp) k(oid, corp) WHERE k.corp ~* '(set_config|search_path)';
      f_mut := c_mut; v_iter := 0;
      WHILE cardinality(f_mut) > 0 AND v_iter < 100 LOOP
        v_iter := v_iter + 1;
        -- r5f (#825 NO-GO): tiparele pe BUCĂȚI de ~4000 de caractere, nu o singură alternanță: cu ~1000 de nume lungi în
        -- frontieră, motorul de regex refuză („invalid memory alloc request size” / „regular expression is too complex”) —
        -- poarta ar da eroare unde E2a răspunde (testul „frontieră largă”), iar compilarea crește pătratic. Fiecare nume dă două
        -- alternative: calificat (s = NULL, oricui) și necalificat (s = NULL în afara platformei; s = schema platformei: doar
        -- dacă e în calea fixată a funcției sau calea e nefixată).
        -- r5f (#825 NO-GO, P1): și SCHEMA se escapează (nsx), ca numele: o schemă construită („x)(?=x)y(x”) ar închide grupul
        -- comun și ar face bucata (deci toate numele ei) imposibil de potrivit — verde fals; nsp (brut) rămâne doar pentru s
        WITH t AS (SELECT n2.nspname::text nsp, regexp_replace(n2.nspname, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') nsx,
                          regexp_replace(q.proname, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') nume
                     FROM pg_proc q JOIN pg_namespace n2 ON n2.oid = q.pronamespace WHERE q.oid = ANY (f_mut)),
             y AS (SELECT NULL::text s, t.nsx || '"?[[:space:]]*\.[[:space:]]*"?' || t.nume f FROM t
                   UNION ALL SELECT CASE WHEN t.nsp = ANY (c_scheme_platforma) THEN t.nsp END, t.nume FROM t)
        SELECT coalesce(array_agg(z.s), '{}'), coalesce(array_agg(c_st || '(' || z.alt || ')' || c_dr), '{}') INTO a_s, a_x
          FROM (SELECT y2.s, string_agg(y2.f, '|') alt
                  FROM (SELECT y.s, y.f, (sum(length(y.f) + 1) OVER (PARTITION BY y.s ORDER BY y.f ROWS UNBOUNDED PRECEDING) - 1) / 4000 b FROM y) y2
                 GROUP BY y2.s, y2.b) z;
        -- bucata în exterior (LATERAL … OFFSET 0: nu se aplatizează), corpurile în interior — fiecare tipar se compilează o dată;
        -- CASE fixează ordinea: întâi filtrele ieftine, regex-ul ultimul (planificatorul l-ar evalua primul)
        n_mut := ARRAY(SELECT DISTINCT m.oid FROM unnest(a_s, a_x) p(s, x)
                         CROSS JOIN LATERAL (SELECT k.oid FROM unnest(k_oid, k_corp, k_cale) k(oid, corp, cale)
                                              WHERE CASE WHEN k.oid = ANY (c_mut) THEN false
                                                         WHEN p.s IS NULL OR k.cale IS NULL OR p.s = ANY (string_to_array(k.cale, ',')) THEN k.corp ~* p.x
                                                         ELSE false END OFFSET 0) m);
        c_mut := c_mut || n_mut; f_mut := n_mut;
      END LOOP;
      IF v_iter >= 100 THEN v := array_append(v, 'propagarea mutatorilor de cale nu converge (citire nerevizuită)'); END IF;
      -- închiderea: frontiera = elementele adăugate în iterația precedentă (view-urile noi intră în frontiera aceleiași iterații,
      -- ca în E2a, unde sunt adăugate înaintea funcțiilor)
      f_rel := c_rel; f_fn := c_fn; v_iter := 0;
      WHILE (cardinality(f_rel) > 0 OR cardinality(f_fn) > 0) AND v_iter < 100 LOOP
        v_iter := v_iter + 1;
        n_rel := ARRAY(SELECT DISTINCT rw.ev_class FROM pg_depend d JOIN pg_rewrite rw ON rw.oid = d.objid
                        WHERE d.classid = 'pg_rewrite'::regclass
                          AND ((d.refclassid = 'pg_class'::regclass AND d.refobjid = ANY (f_rel))
                               OR (d.refclassid = 'pg_proc'::regclass AND d.refobjid = ANY (f_fn)))
                          AND rw.ev_class <> ALL (c_rel));
        c_rel := c_rel || n_rel; f_rel := f_rel || n_rel;
        -- r5f (#825 NO-GO): aceleași bucăți de tipare ca la mutatori, cu schema escapată (P1; vezi mai sus)
        WITH t AS (SELECT n2.nspname::text nsp, regexp_replace(n2.nspname, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') nsx,
                          regexp_replace(c.relname, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g') nume
                     FROM pg_class c JOIN pg_namespace n2 ON n2.oid = c.relnamespace WHERE c.oid = ANY (f_rel)
                   UNION
                   SELECT n2.nspname::text, regexp_replace(n2.nspname, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g'),
                          regexp_replace(q.proname, '([.^$*+?()\[\]{}|\\])', '\\\1', 'g')
                     FROM pg_proc q JOIN pg_namespace n2 ON n2.oid = q.pronamespace WHERE q.oid = ANY (f_fn)),
             y AS (SELECT NULL::text s, t.nsx || '"?[[:space:]]*\.[[:space:]]*"?' || t.nume f FROM t
                   UNION ALL SELECT CASE WHEN t.nsp = ANY (c_scheme_platforma) THEN t.nsp END, t.nume FROM t)
        SELECT coalesce(array_agg(z.s), '{}'), coalesce(array_agg(c_st || '(' || z.alt || ')' || c_dr), '{}') INTO a_s, a_x
          FROM (SELECT y2.s, string_agg(y2.f, '|') alt
                  FROM (SELECT y.s, y.f, (sum(length(y.f) + 1) OVER (PARTITION BY y.s ORDER BY y.f ROWS UNBOUNDED PRECEDING) - 1) / 4000 b FROM y) y2
                 GROUP BY y2.s, y2.b) z;
        -- schemele platformei: necalificat doar dacă schema e în calea funcției; calea e necunoscută dacă nu e fixată SAU dacă
        -- funcția e mutator (r15)
        n_fn := ARRAY(SELECT DISTINCT m.oid FROM unnest(a_s, a_x) p(s, x)
                        CROSS JOIN LATERAL (SELECT k.oid FROM unnest(k_oid, k_corp, k_cale) k(oid, corp, cale)
                                             WHERE CASE WHEN k.oid = ANY (c_fn) THEN false
                                                        WHEN p.s IS NULL OR k.oid = ANY (c_mut) OR k.cale IS NULL OR p.s = ANY (string_to_array(k.cale, ','))
                                                          THEN k.corp ~* p.x
                                                        ELSE false END OFFSET 0) m);
        -- sau depind de ceva din frontieră în catalog (BEGIN ATOMIC)
        n_fn := n_fn || ARRAY(SELECT k.oid FROM unnest(k_oid) k(oid) WHERE k.oid <> ALL (c_fn) AND k.oid <> ALL (n_fn)
                                AND EXISTS (SELECT 1 FROM pg_depend d WHERE d.classid = 'pg_proc'::regclass AND d.objid = k.oid
                                               AND ((d.refclassid = 'pg_class'::regclass AND d.refobjid = ANY (f_rel))
                                                    OR (d.refclassid = 'pg_proc'::regclass AND d.refobjid = ANY (f_fn)))));
        c_fn := c_fn || n_fn;
        f_rel := n_rel; f_fn := n_fn;
      END LOOP;
      IF v_iter >= 100 THEN v := array_append(v, 'închiderea citirilor nu converge (citire nerevizuită)'); END IF;
      -- r5f (#825 NO-GO, P1): un element al închiderii (sau mutator) al cărui nume nu se poate căuta sigur în corpuri → refuz:
      -- schemă cu caractere speciale de regex (E2a dă eroare pe ea, deci rămâne închisă — poarta nouă refuză la fel, nu dă
      -- verde) sau ghilimele în schemă / nume (în corp apar dublate, „"x""y"” — nicio expresie nu le găsește; în E2a: verde fals)
      IF EXISTS (SELECT 1 FROM (SELECT c.relname::text nume, c.relnamespace ns FROM pg_class c WHERE c.oid = ANY (c_rel)
                                UNION ALL SELECT q.proname::text, q.pronamespace FROM pg_proc q WHERE q.oid = ANY (c_fn || c_mut)) o
                  JOIN pg_namespace n2 ON n2.oid = o.ns
                 WHERE n2.nspname ~ '[.^$*+?()\[\]{}|\\"]' OR o.nume ~ '"') THEN
        v := array_append(v, 'un nume din închiderea citirilor nu se poate căuta sigur în corpuri (schemă cu caractere speciale de regex / nume cu ghilimele) (citire nerevizuită)');
      END IF;
      -- r5g (#825, Jak P1): invocarea IMPLICITĂ cheamă o funcție fără să-i scrie numele — operatorul (oprcode / oprrest /
      -- oprjoin: „OPERATOR(s.#!#) x”, infix / prefix), cast-ul (castfunc: „x::tip”), agregatul (aggtransfn / aggfinalfn /
      -- aggcombinefn / aggserialfn / aggdeserialfn / aggmtransfn / aggminvtransfn / aggmfinalfn; agregatul e prolang
      -- internal, deci nu e candidat și numele lui nu se caută); corpurile ne-ATOMIC n-au nici dependențe în catalog. Nu se
      -- propagă (forma infix nu se poate căuta sigur în corpuri): funcția-suport în închidere sau mutator de cale → refuz
      -- explicit, oricine ar folosi operatorul / cast-ul / agregatul (fals-pozitive acceptate). Pe prod: 0 (suportul din afara
      -- pg_catalog e doar C, în extensions — niciodată candidat). Celelalte obiecte din catalog: regula P1-D, mai jos
      FOR k_s IN SELECT x.d FROM (
          SELECT format('operator %s → %s', o.oid::regoperator, f.f::regprocedure) d
            FROM pg_operator o CROSS JOIN LATERAL unnest(ARRAY[o.oprcode::oid, o.oprrest::oid, o.oprjoin::oid]) f(f)
           WHERE f.f = ANY (c_fn || c_mut)
          UNION
          SELECT format('cast (%s AS %s) → %s', c.castsource::regtype, c.casttarget::regtype, c.castfunc::regprocedure)
            FROM pg_cast c WHERE c.castfunc = ANY (c_fn || c_mut)
          UNION
          SELECT format('agregat %s → %s', a.aggfnoid::regprocedure, f.f::regprocedure)
            FROM pg_aggregate a CROSS JOIN LATERAL unnest(ARRAY[a.aggtransfn::oid, a.aggfinalfn::oid, a.aggcombinefn::oid, a.aggserialfn::oid,
                                                                a.aggdeserialfn::oid, a.aggmtransfn::oid, a.aggminvtransfn::oid, a.aggmfinalfn::oid]) f(f)
           WHERE f.f = ANY (c_fn || c_mut)) x
        ORDER BY x.d COLLATE "C"
      LOOP
        v := array_append(v, 'invocare implicită neanalizată: ' || k_s || ' (funcție-suport din închiderea citirilor sau mutator de cale) (citire nerevizuită)');
      END LOOP;
      -- r5g (#825) NO-GO P1-C: țintele fn_izo_* ies din c_fn după propagare (API-ul revizuit, sub ștampila E2a; un DEFINER
      -- fn_izo_* nu e „DEFINER din afara registrului”). Fără sămânța E3 c_fn nu conține fn_izo_* (nici candidați, nici
      -- SQL dinamic), deci aici nu schimbă nimic
      c_fn := ARRAY(SELECT x.f FROM unnest(c_fn) x(f) JOIN pg_proc q ON q.oid = x.f
                     WHERE NOT (q.pronamespace = 'public'::regnamespace AND q.proname LIKE 'fn\_izo\_%'));
      -- r5g (#825) NO-GO P1-D: invocarea implicită prin EXPRESII DIN CATALOG — CHECK pe domeniu / tabel, DEFAULT, coloană
      -- generată, expresie de index, trigger (și event trigger), politică, statistici, I/O de tip, clasă de operatori …: un
      -- DEFINER care scrie / convertește / sortează le pornește fără să numească funcția. Orice rând pg_depend spre o funcție
      -- din închidere al cărui obiect nu e propagat mai sus (view / regulă: pg_rewrite; funcție: pg_proc — candidații prin
      -- propagare, agregatele prin regula de deasupra; operator / cast: regula de deasupra) → refuz explicit, cu obiectul numit,
      -- în afara listei revizuite (c_implicite_revizuite).
      -- r5h (#825 r5g NO-GO, Jak P1): și spre MUTATORII de cale (c_mut), ca spre închidere: un trigger INVOKER care face
      -- set_config('search_path', 'storage, public', true) pe un tabel auxiliar, pornit de un DEFINER cu cale fixă care inserează
      -- acolo și apoi cheamă necalificat un cititor de platformă, schimbă calea efectivă FĂRĂ ca DEFINER-ul să numească mutatorul
      -- (deci el nu devine mutator, iar apelul necalificat se judecă pe calea declarată). Refuz explicit, cu obiectul numit; pe
      -- prod: 12 obiecte peste mutatori (11 trigger-e + issue_graphql_placeholder; tr_check_filters / issue_pg_net_access și în
      -- închidere), toate pe lista revizuită, cu corpul în amprentă
      FOR k_s IN SELECT x.d FROM (
          SELECT DISTINCT format('%s → %s%s', pg_describe_object(d.classid, d.objid, d.objsubid), d.refobjid::regprocedure,
                                 CASE WHEN d.refobjid = ANY (c_fn) THEN ' (obiect din catalog care cheamă o funcție din închiderea citirilor)'
                                      ELSE ' (obiect din catalog care cheamă un mutator de cale)' END) d
            FROM pg_depend d JOIN pg_proc q ON q.oid = d.refobjid JOIN pg_language l ON l.oid = q.prolang
                 CROSS JOIN LATERAL pg_identify_object(d.classid, d.objid, d.objsubid) o
                 CROSS JOIN LATERAL pg_identify_object('pg_proc'::regclass, q.oid, 0) f
           WHERE d.refclassid = 'pg_proc'::regclass AND d.refobjid = ANY (c_fn || c_mut)
             AND d.classid NOT IN ('pg_rewrite'::regclass, 'pg_proc'::regclass, 'pg_operator'::regclass, 'pg_cast'::regclass)
             AND format('%s %s=%s', o.type, o.identity, md5(concat_ws('|', o.type, o.identity, f.identity, pg_get_userbyid(q.proowner), q.prosecdef::text, coalesce(q.proconfig::text, ''), l.lanname, md5(q.prosrc || '|' || coalesce(q.prosqlbody::text, ''))))) <> ALL (c_implicite_revizuite)) x
        ORDER BY x.d COLLATE "C"
      LOOP
        v := array_append(v, 'invocare implicită neanalizată: ' || k_s || ' (citire nerevizuită)');
      END LOOP;
      IF EXISTS (SELECT 1 FROM pg_class vw WHERE vw.oid = ANY (c_rel)   -- alias ≠ variabila v
                  AND (vw.relkind = 'm' OR (vw.relkind = 'v' AND NOT coalesce(vw.reloptions && ARRAY['security_invoker=true','security_invoker=on','security_invoker=1'], false)))) THEN
        v := array_append(v, 'un view / view materializat citește registrul fără security_invoker (citire nerevizuită)');
      END IF;
      IF EXISTS (SELECT 1 FROM pg_proc p WHERE p.oid = ANY (c_fn) AND p.prosecdef) THEN
        v := array_append(v, 'o funcție DEFINER din afara registrului poate citi registrul — direct, prin view sau tranzitiv (citire nerevizuită)');
      END IF;
    END;
    -- writer-ul are exact ce-i trebuie (un GRANT retras ar lăsa activarea admisă și importul nefuncțional)
    -- câte un privilegiu pe rând: has_table_privilege(…, 'A,B') e adevărat dacă există ORICARE (Codex r4 8)
    IF EXISTS (SELECT 1 FROM (VALUES ('magazie_bucati','SELECT'), ('magazie_bucati','INSERT'), ('magazie_bucati','UPDATE'),
                                     ('magazie_bucati_evenimente','SELECT'), ('magazie_bucati_evenimente','INSERT'),
                                     ('magazie_bucati_miscari','SELECT'), ('magazie_bucati_miscari','INSERT'),
                                     ('izo_importuri','SELECT'), ('izo_importuri','INSERT'), ('izo_importuri','UPDATE'),
                                     ('izo_proiect_config','SELECT'), ('izo_proiect_config','INSERT'), ('izo_proiect_config','UPDATE'),
                                     ('izo_atribuiri','SELECT')) d(t, pr)
                WHERE NOT has_table_privilege('izo_registru_writer', 'public.' || d.t, d.pr))
       OR NOT (true
            AND has_sequence_privilege('izo_registru_writer', 'public.izo_server_ver_seq', 'USAGE')
            AND has_sequence_privilege('izo_registru_writer', 'public.magazie_bucati_id_seq', 'USAGE')
            AND has_sequence_privilege('izo_registru_writer', 'public.magazie_bucati_evenimente_id_seq', 'USAGE')
            AND has_sequence_privilege('izo_registru_writer', 'public.magazie_bucati_miscari_id_seq', 'USAGE')
            AND has_sequence_privilege('izo_registru_writer', 'public.izo_importuri_id_seq', 'USAGE')) THEN
      v := array_append(v, 'drepturile writer-ului (tabele / secvențe) incomplete');
    END IF;
    IF EXISTS (SELECT 1 FROM unnest(ARRAY['anon','authenticated','service_role']) a(n) WHERE has_table_privilege(a.n, 'public.magazie_bucati', 'TRUNCATE')) THEN
      v := array_append(v, 'TRUNCATE pe magazie_bucati pentru un rol API');
    END IF;
    -- definițiile (nu doar numele): amprenta curentă = cea fixată la migrare (review #806 r2)
    IF public.fn_izo_porti_definitii() IS DISTINCT FROM
       substring(obj_description('public.fn_izo_porti_definitii()'::regprocedure, 'pg_proc') FROM '^porti=([0-9a-f]{32})$') THEN
      v := array_append(v, 'definițiile porților diferă de amprenta de la migrare (trigger / politică / funcție / ACL modificat)');
    END IF;
    -- E3 (20261103b): poarta documentelor de intrare, chemată de aici, ca orice activare / import E2a s-o includă (r5d §13.1)
    v := v || public.fn_izo_porti_e3_lipsa();
    v := v || public.fn_izo_porti_e3b_lipsa();
    v := v || public.fn_izo_porti_e4_lipsa();
    v := v || public.fn_izo_porti_e4b_lipsa();
    RETURN v;
  END $f$;
 v_impl := (SELECT coalesce(array_agg(x.d ORDER BY x.d COLLATE "C"), '{}'::text[])
       FROM (SELECT DISTINCT format('%s|%s|%s', o.type, o.identity, f.identity) d
               FROM pg_depend d JOIN pg_proc q ON q.oid = d.refobjid
                    CROSS JOIN LATERAL pg_identify_object(d.classid, d.objid, d.objsubid) o
                    CROSS JOIN LATERAL pg_identify_object('pg_proc'::regclass, q.oid, 0) f
